                      'h-4 w-4',
                      account.sync_status === 'syncing' && 'animate-spin'
                    )} />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-destructive hover:text-destructive"
                    onClick={() => {
                      setSelectedAccount(account);
                      setShowDeleteDialog(true);
