                      </Button>
                    </div>
                  </div>
                </div>

                {formData.provider_type === 'microsoft' && (
                  <div className="space-y-2">
                    <Label htmlFor="tenantId">Tenant ID (optional)</Label>
                    <Input
                      id="tenantId"
                      placeholder="common (for multi-tenant) or your tenant ID"
