            {/* IMAP Configuration */}
            {formData.provider_type === 'imap' && (
              <>
                {/* Email Provider Preset */}
                <div className="grid gap-4 grid-cols-2">
                  <div className="space-y-2">
                    <Label>Email Provider</Label>
                    <Select value={formData.preset} onValueChange={handlePresetChange}>
