                      placeholder="you@example.com"
                      value={formData.email_address}
                      onChange={(e) => setFormData((prev) => ({ ...prev, email_address: e.target.value }))}
                    />
                  </div>
                </div>

                <Tabs defaultValue="imap" className="w-full">
                  <TabsList className="grid w-full grid-cols-2">
                    <TabsTrigger value="imap">
                      <Server className="h-4 w-4 mr-2" />
                      IMAP (Incoming)
                    </TabsTrigger>
                    <TabsTrigger value="smtp">
                      <Mail className="h-4 w-4 mr-2" />
                      SMTP (Outgoing)
                    </TabsTrigger>
                  </TabsList>

                  <TabsContent value="imap" className="space-y-4 pt-4">
                    <div className="grid gap-4 grid-cols-2">
                      <div className="space-y-2">
                        <Label htmlFor="imapHost">IMAP Server</Label>
                        <Input
                          id="imapHost"
                          placeholder="imap.example.com"
                          value={formData.imap_host}
                          onChange={(e) => setFormData((prev) => ({ ...prev, imap_host: e.target.value }))}
                        />
                      </div>
                      <div className="grid gap-4 grid-cols-2">
                        <div className="space-y-2">
                          <Label htmlFor="imapPort">Port</Label>
                          <Input
                            id="imapPort"
                            type="number"
                            value={formData.imap_port}
                            onChange={(e) => setFormData((prev) => ({ ...prev, imap_port: parseInt(e.target.value) || 993 }))}
                          />
                        </div>
                        <div className="space-y-2">
                          <Label>Encryption</Label>
                          <Select
                            value={formData.imap_encryption}
                            onValueChange={(v) => setFormData((prev) => ({ ...prev, imap_encryption: v as 'ssl' | 'tls' | 'none' }))}
                          >
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="ssl">SSL/TLS</SelectItem>
                              <SelectItem value="tls">STARTTLS</SelectItem>
                              <SelectItem value="none">None</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      </div>
                    </div>
                    <div className="grid gap-4 grid-cols-2">
                      <div className="space-y-2">
                        <Label htmlFor="imapUsername">Username</Label>
                        <Input
                          id="imapUsername"
                          placeholder="Leave blank to use email"
                          value={formData.imap_username}
                          onChange={(e) => setFormData((prev) => ({ ...prev, imap_username: e.target.value }))}
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="imapPassword">Password / App Password</Label>
                        <div className="relative">
                          <Input
                            id="imapPassword"
                            type={showPasswords ? 'text' : 'password'}
                            value={formData.imap_password}
                            onChange={(e) => setFormData((prev) => ({ ...prev, imap_password: e.target.value }))}
                          />
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            className="absolute right-0 top-0 h-full"
                            onClick={() => setShowPasswords(!showPasswords)}
                          >
                            {showPasswords ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                          </Button>
                        </div>
                      </div>
                    </div>
                  </TabsContent>

                  <TabsContent value="smtp" className="space-y-4 pt-4">
                    <div className="flex items-center gap-2 mb-4">
                      <Switch
                        id="sameCredentials"
                        checked={formData.use_same_credentials}
                        onCheckedChange={(checked) => setFormData((prev) => ({ ...prev, use_same_credentials: checked }))}
                      />
                      <Label htmlFor="sameCredentials">Use same credentials as IMAP</Label>
                    </div>

                    <div className="grid gap-4 grid-cols-2">
                      <div className="space-y-2">
                        <Label htmlFor="smtpHost">SMTP Server</Label>
                        <Input
                          id="smtpHost"
                          placeholder="smtp.example.com"
                          value={formData.smtp_host}
                          onChange={(e) => setFormData((prev) => ({ ...prev, smtp_host: e.target.value }))}
                        />
                      </div>
                      <div className="grid gap-4 grid-cols-2">
                        <div className="space-y-2">
                          <Label htmlFor="smtpPort">Port</Label>
                          <Input
                            id="smtpPort"
                            type="number"
                            value={formData.smtp_port}
                            onChange={(e) => setFormData((prev) => ({ ...prev, smtp_port: parseInt(e.target.value) || 587 }))}
                          />
                        </div>
                        <div className="space-y-2">
                          <Label>Encryption</Label>
                          <Select
                            value={formData.smtp_encryption}
                            onValueChange={(v) => setFormData((prev) => ({ ...prev, smtp_encryption: v as 'ssl' | 'tls' | 'none' }))}
                          >
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="ssl">SSL/TLS</SelectItem>
                              <SelectItem value="tls">STARTTLS</SelectItem>
                              <SelectItem value="none">None</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      </div>
                    </div>

                    {!formData.use_same_credentials && (
                      <div className="grid gap-4 grid-cols-2">
                        <div className="space-y-2">
                          <Label htmlFor="smtpUsername">Username</Label>
                          <Input
                            id="smtpUsername"
                            value={formData.smtp_username}
                            onChange={(e) => setFormData((prev) => ({ ...prev, smtp_username: e.target.value }))}
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="smtpPassword">Password</Label>
                          <Input
                            id="smtpPassword"
                            type={showPasswords ? 'text' : 'password'}
                            value={formData.smtp_password}
                            onChange={(e) => setFormData((prev) => ({ ...prev, smtp_password: e.target.value }))}
                          />
                        </div>
                      </div>
                    )}
                  </TabsContent>
                </Tabs>

                {/* Test Result */}
                <AnimatePresence>
                  {testResult && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      exit={{ opacity: 0, height: 0 }}
                    >
                      <div
                        className={cn(
                          'flex items-center gap-3 p-4 rounded-lg',
                          testResult.success
                            ? 'bg-success/10 border border-success/30'
                            : 'bg-destructive/10 border border-destructive/30'
                        )}
                      >
                        {testResult.success ? (
                          <>
                            <CheckCircle className="h-5 w-5 text-success" />
                            <span className="font-medium text-success">Connection successful!</span>
                          </>
                        ) : (
                          <>
                            <AlertCircle className="h-5 w-5 text-destructive" />
                            <div>
                              <span className="font-medium text-destructive">Connection failed</span>
                              {testResult.error && (
                                <p className="text-sm text-muted-foreground mt-1">{testResult.error}</p>
                              )}
                            </div>
                          </>
                        )}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </>
            )}
          </div>

          <DialogFooter className="gap-2">
            {formData.provider_type === 'imap' ? (
              <>
                <Button variant="outline" onClick={handleTestConnection} disabled={isTesting || !formData.email_address || !formData.imap_password}>
                  {isTesting ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Testing...
                    </>
                  ) : (
                    <>
                      <Check className="h-4 w-4 mr-2" />
                      Test Connection
                    </>
                  )}
                </Button>
                <Button onClick={handleSave} disabled={isSaving || !formData.email_address || !formData.imap_password}>
                  {isSaving ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    'Add Account'
                  )}
                </Button>
              </>
            ) : (
              <Button
                onClick={handleStartOAuth}
                disabled={isOAuthPending || !formData.oauth_client_id || !formData.oauth_client_secret}
                className="w-full"
              >
                {isOAuthPending ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Connecting...
                  </>
                ) : (
                  <>
                    <ExternalLink className="h-4 w-4 mr-2" />
                    Connect with {formData.provider_type === 'gmail' ? 'Google' : 'Microsoft'}
                  </>
                )}
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove Email Account</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to remove "{selectedAccount?.email_address}"? This will delete all synced emails from this account. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Remove Account
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  X,
  Minus,
  Maximize2,
  Minimize2,
  Send,
  Paperclip,
  Image,
  Link,
  Smile,
  MoreHorizontal,
  Bold,
  Italic,
  Underline,
  List,
  ListOrdered,
  AlignLeft,
  Trash2,
  ChevronDown,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Dialog,
  DialogContent,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { cn } from '@/lib/utils';
import { EmailAccount } from '@/hooks/useEmailAccounts';
import { Email } from '@/hooks/useEmails';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

interface EmailComposeDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: 'new' | 'reply' | 'forward';
  replyToEmail?: Email;
  accounts: EmailAccount[];
}

export function EmailComposeDialog({
  open,
  onOpenChange,
  mode,
  replyToEmail,
  accounts,
}: EmailComposeDialogProps) {
  const [selectedAccountId, setSelectedAccountId] = useState<string>('');
  const [to, setTo] = useState('');
  const [cc, setCc] = useState('');
  const [bcc, setBcc] = useState('');
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [showCcBcc, setShowCcBcc] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);

  // Initialize form based on mode
  useEffect(() => {
    if (!open) return;

    if (accounts.length > 0 && !selectedAccountId) {
      setSelectedAccountId(accounts[0].id);
    }

    if (mode === 'reply' && replyToEmail) {
      setTo(replyToEmail.from_address);
      setSubject(`Re: ${replyToEmail.subject || ''}`);
      setBody(`\n\n---\nOn ${new Date(replyToEmail.received_at).toLocaleString()}, ${replyToEmail.from_name || replyToEmail.from_address} wrote:\n\n${replyToEmail.body_text || ''}`);
    } else if (mode === 'forward' && replyToEmail) {
      setTo('');
      setSubject(`Fwd: ${replyToEmail.subject || ''}`);
      setBody(`\n\n---\nForwarded message:\nFrom: ${replyToEmail.from_address}\nDate: ${new Date(replyToEmail.received_at).toLocaleString()}\nSubject: ${replyToEmail.subject}\n\n${replyToEmail.body_text || ''}`);
    } else {
      setTo('');
      setCc('');
      setBcc('');
      setSubject('');
      setBody('');
    }
  }, [open, mode, replyToEmail, accounts, selectedAccountId]);

  const handleSend = async () => {
    if (!selectedAccountId || !to) {
      toast.error('Please fill in required fields');
      return;
    }

    setIsSending(true);

    try {
      const response = await supabase.functions.invoke('email-send', {
        body: {
          accountId: selectedAccountId,
          to: to.split(',').map((e) => e.trim()),
          cc: cc ? cc.split(',').map((e) => e.trim()) : [],
          bcc: bcc ? bcc.split(',').map((e) => e.trim()) : [],
          subject,
          body,
          replyToMessageId: mode === 'reply' ? replyToEmail?.message_id : undefined,
        },
      });

      if (response.error) throw response.error;

      toast.success('Email sent successfully');
      onOpenChange(false);
    } catch (err: any) {
      console.error('Error sending email:', err);
      toast.error(err.message || 'Failed to send email');
    } finally {
      setIsSending(false);
    }
  };

  const handleDiscard = () => {
    setTo('');
    setCc('');
    setBcc('');
    setSubject('');
    setBody('');
    onOpenChange(false);
  };

  const selectedAccount = accounts.find((a) => a.id === selectedAccountId);

  if (isMinimized) {
    return (
      <motion.div
        initial={{ y: 100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="fixed bottom-0 right-4 w-72 bg-card border rounded-t-lg shadow-lg z-50"
      >
        <div
          className="flex items-center justify-between px-3 py-2 border-b cursor-pointer"
          onClick={() => setIsMinimized(false)}
        >
          <span className="font-medium text-sm truncate">
            {subject || 'New Message'}
          </span>
          <div className="flex items-center gap-1">
            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={(e) => {
              e.stopPropagation();
              setIsMinimized(false);
            }}>
              <Maximize2 className="h-3.5 w-3.5" />
            </Button>
            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={(e) => {
              e.stopPropagation();
              handleDiscard();
            }}>
              <X className="h-3.5 w-3.5" />
            </Button>
          </div>
        </div>
      </motion.div>
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl p-0 gap-0">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b bg-muted/30">
          <h3 className="font-semibold">
            {mode === 'reply' ? 'Reply' : mode === 'forward' ? 'Forward' : 'New Message'}
          </h3>
          <div className="flex items-center gap-1">
            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setIsMinimized(true)}>
              <Minus className="h-4 w-4" />
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => onOpenChange(false)}>
              <X className="h-4 w-4" />
            </Button>
          </div>
        </div>

        {/* Form */}
        <div className="p-4 space-y-3">
          {/* From Account */}
          {accounts.length > 1 && (
            <div className="flex items-center gap-2">
              <Label className="w-12 text-right text-muted-foreground text-sm">From</Label>
              <Select value={selectedAccountId} onValueChange={setSelectedAccountId}>
                <SelectTrigger className="flex-1">
                  <SelectValue placeholder="Select account" />
                </SelectTrigger>
                <SelectContent>
                  {accounts.map((account) => (
                    <SelectItem key={account.id} value={account.id}>
                      {account.display_name || account.email_address}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* To */}
          <div className="flex items-center gap-2">
            <Label className="w-12 text-right text-muted-foreground text-sm">To</Label>
            <Input
              placeholder="recipient@example.com"
              value={to}
              onChange={(e) => setTo(e.target.value)}
              className="flex-1"
            />
            <Button
              variant="ghost"
              size="sm"
              className="text-xs text-muted-foreground"
              onClick={() => setShowCcBcc(!showCcBcc)}
            >
              Cc/Bcc
            </Button>
          </div>

          {/* Cc/Bcc */}
          {showCcBcc && (
            <>
              <div className="flex items-center gap-2">
                <Label className="w-12 text-right text-muted-foreground text-sm">Cc</Label>
                <Input
                  placeholder="cc@example.com"
                  value={cc}
                  onChange={(e) => setCc(e.target.value)}
                  className="flex-1"
                />
              </div>
              <div className="flex items-center gap-2">
                <Label className="w-12 text-right text-muted-foreground text-sm">Bcc</Label>
                <Input
                  placeholder="bcc@example.com"
                  value={bcc}
                  onChange={(e) => setBcc(e.target.value)}
                  className="flex-1"
                />
              </div>
            </>
          )}

          {/* Subject */}
          <div className="flex items-center gap-2">
            <Label className="w-12 text-right text-muted-foreground text-sm">Subject</Label>
            <Input
              placeholder="Subject"
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              className="flex-1"
            />
          </div>
        </div>

        {/* Rich Text Toolbar */}
        <div className="flex items-center gap-1 px-4 py-2 border-t border-b">
          <Button variant="ghost" size="icon" className="h-7 w-7">
            <Bold className="h-4 w-4" />
          </Button>
          <Button variant="ghost" size="icon" className="h-7 w-7">
            <Italic className="h-4 w-4" />
          </Button>
          <Button variant="ghost" size="icon" className="h-7 w-7">
            <Underline className="h-4 w-4" />
          </Button>
          <div className="w-px h-5 bg-border mx-1" />
          <Button variant="ghost" size="icon" className="h-7 w-7">
            <List className="h-4 w-4" />
          </Button>
          <Button variant="ghost" size="icon" className="h-7 w-7">
            <ListOrdered className="h-4 w-4" />
          </Button>
          <div className="w-px h-5 bg-border mx-1" />
          <Button variant="ghost" size="icon" className="h-7 w-7">
            <Link className="h-4 w-4" />
          </Button>
          <Button variant="ghost" size="icon" className="h-7 w-7">
            <Image className="h-4 w-4" />
          </Button>
        </div>

        {/* Body */}
        <div className="px-4 py-2">
          <Textarea
            placeholder="Write your message..."
            value={body}
            onChange={(e) => setBody(e.target.value)}
            className="min-h-[200px] resize-none border-0 focus-visible:ring-0 p-0"
          />
        </div>

        {/* Footer */}
