  const isSelected = (id: string) => selectedIds.includes(id);
  const isAllSelected = documents.length > 0 && selectedIds.length === documents.length;

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortBy !== field) return null;
    return sortDirection === 'asc' ? (
      <ChevronUp className="h-3 w-3 ml-1" />
    ) : (
      <ChevronDown className="h-3 w-3 ml-1" />
    );
  };

  if (documents.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <div className="text-center">
          <File className="h-12 w-12 text-muted-foreground mx-auto mb-3" />
          <h3 className="text-lg font-medium">No documents</h3>
          <p className="text-muted-foreground text-sm">
            Upload files or create a folder to get started
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-auto">
      <Table>
        <TableHeader className="sticky top-0 bg-card z-10">
          <TableRow>
            <TableHead className="w-10">
              <Checkbox
                checked={isAllSelected}
                onCheckedChange={toggleSelectAll}
              />
            </TableHead>
            <TableHead className="w-10"></TableHead>
            <TableHead>
              <button
                className="flex items-center hover:text-foreground"
                onClick={() => onSortChange('name')}
              >
                Name
                <SortIcon field="name" />
              </button>
            </TableHead>
            <TableHead>
              <button
                className="flex items-center hover:text-foreground"
                onClick={() => onSortChange('date')}
              >
                Modified
                <SortIcon field="date" />
              </button>
            </TableHead>
            <TableHead>
              <button
                className="flex items-center hover:text-foreground"
                onClick={() => onSortChange('size')}
              >
                Size
                <SortIcon field="size" />
              </button>
            </TableHead>
            <TableHead>
              <button
                className="flex items-center hover:text-foreground"
                onClick={() => onSortChange('type')}
              >
                Type
                <SortIcon field="type" />
              </button>
            </TableHead>
            {showDetails && (
              <>
                <TableHead>Status</TableHead>
                <TableHead>Uploaded By</TableHead>
              </>
            )}
            <TableHead className="w-10"></TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {documents.map((doc) => (
            <TableRow
              key={doc.id}
              className={cn(
                'cursor-pointer',
                isSelected(doc.id) && 'bg-primary/5'
              )}
              onClick={() => onDocumentClick(doc)}
              onDoubleClick={() => onDocumentDoubleClick(doc)}
            >
              <TableCell onClick={(e) => e.stopPropagation()}>
                <Checkbox
                  checked={isSelected(doc.id)}
                  onCheckedChange={() => toggleSelection(doc.id)}
                />
              </TableCell>
              <TableCell onClick={(e) => e.stopPropagation()}>
                <Button
                  variant="ghost"
                  size="iconXs"
                  onClick={() => onToggleStar(doc.id)}
                >
                  {doc.is_starred ? (
                    <Star className="h-4 w-4 text-warning fill-warning" />
                  ) : (
                    <StarOff className="h-4 w-4 text-muted-foreground" />
                  )}
                </Button>
              </TableCell>
              <TableCell>
                <div className="flex items-center gap-2">
                  {getFileIcon(doc.file_type)}
                  <span className="font-medium truncate max-w-[200px]">
                    {doc.name}
                  </span>
                  {doc.is_locked && (
                    <Lock className="h-3 w-3 text-warning" />
                  )}
                </div>
              </TableCell>
              <TableCell className="text-muted-foreground">
                {new Date(doc.updated_at).toLocaleDateString()}
              </TableCell>
              <TableCell className="text-muted-foreground">
                {formatSize(doc.file_size)}
              </TableCell>
              <TableCell className="text-muted-foreground uppercase text-xs">
                {doc.file_type}
              </TableCell>
              {showDetails && (
                <>
                  <TableCell>
                    <Badge
                      variant={getStatusVariant(doc.status) as any}
                      className="text-[10px]"
                    >
                      {doc.status}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-muted-foreground text-sm">
                    {doc.uploaded_by_name || 'Unknown'}
                  </TableCell>
                </>
              )}
              <TableCell onClick={(e) => e.stopPropagation()}>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="ghost" size="iconSm">
                      <MoreHorizontal className="h-4 w-4" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem onClick={() => onDocumentClick(doc)}>
                      <Eye className="h-4 w-4 mr-2" />
                      View Details
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => onDownload(doc)}>
                      <Download className="h-4 w-4 mr-2" />
                      Download
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => onViewHistory(doc)}>
                      <History className="h-4 w-4 mr-2" />
                      Version History
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={() => onRename(doc)}>
                      <Edit2 className="h-4 w-4 mr-2" />
                      Rename
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => onCopy(doc)}>
                      <Copy className="h-4 w-4 mr-2" />
                      Copy
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => onMove(doc)}>
                      <Move className="h-4 w-4 mr-2" />
                      Move
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => onShare(doc)}>
                      <Share2 className="h-4 w-4 mr-2" />
                      Share
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      onClick={() => onDelete(doc.id)}
                      className="text-destructive"
                    >
                      <Trash2 className="h-4 w-4 mr-2" />
                      Delete
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

import React, { useState } from 'react';
import { Share2, Link, Copy, Trash2, Mail } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { type DocumentShare } from '@/hooks/useDocumentSharing';

interface DocumentShareDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  documentName: string;
  shares: DocumentShare[];
  onShareWithEmail: (email: string, permission: 'view' | 'comment' | 'edit') => Promise<unknown>;
  onGenerateLink: (permission: 'view' | 'comment' | 'edit') => Promise<string | null>;
  onRemoveShare: (shareId: string) => Promise<unknown>;
  onUpdatePermission: (shareId: string, permission: 'view' | 'comment' | 'edit') => Promise<unknown>;
  onCopyLink: (link: string) => void;
}

export function DocumentShareDialog({
  open,
  onOpenChange,
  documentName,
  shares,
  onShareWithEmail,
  onGenerateLink,
  onRemoveShare,
  onUpdatePermission,
  onCopyLink,
}: DocumentShareDialogProps) {
  const [email, setEmail] = useState('');
  const [permission, setPermission] = useState<'view' | 'comment' | 'edit'>('view');
  const [isSharing, setIsSharing] = useState(false);
  const [generatedLink, setGeneratedLink] = useState<string | null>(null);

  const handleShare = async () => {
    if (!email.trim()) return;

    setIsSharing(true);
    try {
      await onShareWithEmail(email.trim(), permission);
      setEmail('');
    } finally {
      setIsSharing(false);
    }
  };

  const handleGenerateLink = async () => {
    const link = await onGenerateLink(permission);
    if (link) {
      setGeneratedLink(link);
    }
  };

  const emailShares = shares.filter((s) => s.shared_with_email);
  const linkShares = shares.filter((s) => s.share_link);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Share2 className="h-5 w-5" />
            Share Document
          </DialogTitle>
          <DialogDescription>
            Share "{documentName}" with others
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          {/* Share with email */}
          <div className="space-y-3">
            <Label>Share with people</Label>
            <div className="flex gap-2">
              <Input
                type="email"
                placeholder="Enter email address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="flex-1"
              />
              <Select
                value={permission}
                onValueChange={(v) => setPermission(v as any)}
              >
                <SelectTrigger className="w-28">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="view">View</SelectItem>
                  <SelectItem value="comment">Comment</SelectItem>
                  <SelectItem value="edit">Edit</SelectItem>
                </SelectContent>
              </Select>
              <Button onClick={handleShare} disabled={!email.trim() || isSharing}>
                <Mail className="h-4 w-4 mr-1" />
                Share
              </Button>
            </div>
          </div>

          {/* Current shares */}
          {emailShares.length > 0 && (
            <div className="space-y-2">
              <Label className="text-muted-foreground text-xs">People with access</Label>
              <div className="space-y-2">
                {emailShares.map((share) => (
                  <div
                    key={share.id}
                    className="flex items-center justify-between p-2 bg-muted/30 rounded"
                  >
                    <div className="flex items-center gap-2">
                      <Mail className="h-4 w-4 text-muted-foreground" />
                      <span className="text-sm">{share.shared_with_email}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Select
                        value={share.permission}
                        onValueChange={(v) =>
                          onUpdatePermission(share.id, v as any)
                        }
                      >
                        <SelectTrigger className="w-24 h-8">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="view">View</SelectItem>
                          <SelectItem value="comment">Comment</SelectItem>
                          <SelectItem value="edit">Edit</SelectItem>
                        </SelectContent>
                      </Select>
                      <Button
                        variant="ghost"
                        size="iconXs"
                        onClick={() => onRemoveShare(share.id)}
                      >
                        <Trash2 className="h-3 w-3 text-destructive" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <Separator />

          {/* Generate link */}
          <div className="space-y-3">
            <Label>Get shareable link</Label>
            <div className="flex gap-2">
              <Select
                value={permission}
                onValueChange={(v) => setPermission(v as any)}
              >
                <SelectTrigger className="w-28">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="view">View</SelectItem>
                  <SelectItem value="comment">Comment</SelectItem>
                  <SelectItem value="edit">Edit</SelectItem>
                </SelectContent>
              </Select>
              <Button variant="outline" onClick={handleGenerateLink} className="flex-1">
                <Link className="h-4 w-4 mr-1" />
                Generate Link
              </Button>
            </div>

            {generatedLink && (
              <div className="flex items-center gap-2 p-2 bg-muted/30 rounded">
                <Input
                  value={generatedLink}
                  readOnly
                  className="flex-1 text-xs"
                />
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => onCopyLink(generatedLink)}
                >
                  <Copy className="h-4 w-4" />
                </Button>
              </div>
            )}
          </div>

          {/* Active links */}
          {linkShares.length > 0 && (
            <div className="space-y-2">
              <Label className="text-muted-foreground text-xs">Active links</Label>
              <div className="space-y-2">
                {linkShares.map((share) => (
                  <div
                    key={share.id}
                    className="flex items-center justify-between p-2 bg-muted/30 rounded"
                  >
                    <div className="flex items-center gap-2">
                      <Link className="h-4 w-4 text-muted-foreground" />
                      <span className="text-xs text-muted-foreground truncate max-w-[200px]">
                        {share.share_link}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge variant="outline" className="text-[10px]">
                        {share.permission}
                      </Badge>
                      <Button
                        variant="ghost"
                        size="iconXs"
                        onClick={() => onCopyLink(share.share_link!)}
                      >
                        <Copy className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="iconXs"
                        onClick={() => onRemoveShare(share.id)}
                      >
                        <Trash2 className="h-3 w-3 text-destructive" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Done
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { format } from 'date-fns';
import { CalendarIcon, Plus, X, Users, Clock, Video, MapPin, Repeat, Target, CheckCircle2 } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn } from '@/lib/utils';
import type { CreateMeetingInput, CreateAgendaItemInput, CreateParticipantInput } from '@/hooks/useMeetings';

const meetingSchema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
  date: z.date({ required_error: 'Date is required' }),
  startTime: z.string().min(1, 'Start time is required'),
  endTime: z.string().optional(),
  meetingType: z.enum(['online', 'in-person', 'offline']),
  sourceType: z.enum(['zoom', 'teams', 'meet', 'audio', 'manual']),
  meetingLink: z.string().optional(),
  location: z.string().optional(),
  purposeType: z.string().optional(),
  purposeDescription: z.string().optional(),
  recurringSchedule: z.enum(['none', 'daily', 'weekly', 'bi-weekly', 'monthly']).optional(),
  recurringEndDate: z.date().optional(),
});

type MeetingFormData = z.infer<typeof meetingSchema>;

interface ParticipantInput {
  name: string;
  email: string;
  role: string;
}

interface AgendaItemInput {
  title: string;
  duration: number;
  presenterName: string;
}

interface MeetingCreationDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  projectId?: string | null;
  onCreateMeeting: (
    meeting: CreateMeetingInput,
    participants: CreateParticipantInput[],
    agendaItems: CreateAgendaItemInput[]
  ) => Promise<void>;
}

export function MeetingCreationDialog({
  open,
  onOpenChange,
  projectId,
  onCreateMeeting,
}: MeetingCreationDialogProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [participants, setParticipants] = useState<ParticipantInput[]>([]);
  const [agendaItems, setAgendaItems] = useState<AgendaItemInput[]>([]);
  const [expectedOutcomes, setExpectedOutcomes] = useState<string[]>([]);
  const [successCriteria, setSuccessCriteria] = useState<string[]>([]);
  const [newParticipant, setNewParticipant] = useState({ name: '', email: '', role: 'contributor' });
  const [newAgendaItem, setNewAgendaItem] = useState({ title: '', duration: 15, presenterName: '' });
  const [newOutcome, setNewOutcome] = useState('');
  const [newCriterion, setNewCriterion] = useState('');

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    reset,
    formState: { errors },
  } = useForm<MeetingFormData>({
    resolver: zodResolver(meetingSchema),
    defaultValues: {
      meetingType: 'online',
      sourceType: 'teams',
      purposeType: 'status-update',
      recurringSchedule: 'none',
    },
  });

  const selectedDate = watch('date');
  const meetingType = watch('meetingType');
  const recurringSchedule = watch('recurringSchedule');
  const recurringEndDate = watch('recurringEndDate');

  const addParticipant = () => {
    if (newParticipant.name.trim()) {
      setParticipants([...participants, { ...newParticipant }]);
      setNewParticipant({ name: '', email: '', role: 'contributor' });
    }
  };

  const removeParticipant = (index: number) => {
    setParticipants(participants.filter((_, i) => i !== index));
  };

  const addAgendaItem = () => {
    if (newAgendaItem.title.trim()) {
      setAgendaItems([...agendaItems, { ...newAgendaItem }]);
      setNewAgendaItem({ title: '', duration: 15, presenterName: '' });
    }
  };

  const removeAgendaItem = (index: number) => {
    setAgendaItems(agendaItems.filter((_, i) => i !== index));
  };

  const addOutcome = () => {
    if (newOutcome.trim()) {
      setExpectedOutcomes([...expectedOutcomes, newOutcome.trim()]);
      setNewOutcome('');
    }
  };

  const removeOutcome = (index: number) => {
    setExpectedOutcomes(expectedOutcomes.filter((_, i) => i !== index));
  };

  const addCriterion = () => {
    if (newCriterion.trim()) {
      setSuccessCriteria([...successCriteria, newCriterion.trim()]);
      setNewCriterion('');
    }
  };

  const removeCriterion = (index: number) => {
    setSuccessCriteria(successCriteria.filter((_, i) => i !== index));
  };

  const onSubmit = async (data: MeetingFormData) => {
    setIsSubmitting(true);
    try {
      const meetingInput: CreateMeetingInput = {
        project_id: projectId || undefined,
        title: data.title,
        description: data.description,
        date: format(data.date, 'yyyy-MM-dd'),
        start_time: data.startTime,
        end_time: data.endTime,
        meeting_type: data.meetingType,
        source_type: data.sourceType,
        meeting_link: data.meetingLink,
        location: data.location,
        purpose_type: data.purposeType,
        purpose_description: data.purposeDescription,
        expected_outcomes: expectedOutcomes.length > 0 ? expectedOutcomes : undefined,
        success_criteria: successCriteria.length > 0 ? successCriteria : undefined,
        recurring_schedule: data.recurringSchedule || 'none',
        recurring_end_date: data.recurringEndDate ? format(data.recurringEndDate, 'yyyy-MM-dd') : undefined,
        status: 'scheduled',
      };

      const participantInputs: CreateParticipantInput[] = participants.map((p) => ({
        meeting_id: '', // Will be set after meeting creation
        name: p.name,
        email: p.email || undefined,
        role: p.role,
      }));

      const agendaInputs: CreateAgendaItemInput[] = agendaItems.map((a, index) => ({
        meeting_id: '', // Will be set after meeting creation
        title: a.title,
        duration_minutes: a.duration,
        presenter_name: a.presenterName || undefined,
        sort_order: index,
      }));

      await onCreateMeeting(meetingInput, participantInputs, agendaInputs);

      // Reset form
      reset();
      setParticipants([]);
      setAgendaItems([]);
      setExpectedOutcomes([]);
      setSuccessCriteria([]);
      onOpenChange(false);
    } finally {
      setIsSubmitting(false);
    }
  };

  const purposeTypes = [
    { value: 'status-update', label: 'Status Update' },
    { value: 'decision', label: 'Decision Making' },
    { value: 'review', label: 'Review' },
    { value: 'planning', label: 'Planning' },
    { value: 'brainstorming', label: 'Brainstorming' },
    { value: 'kickoff', label: 'Kickoff' },
    { value: 'retrospective', label: 'Retrospective' },
    { value: 'other', label: 'Other' },
  ];

  const roleOptions = [
    { value: 'decision-maker', label: 'Decision Maker' },
    { value: 'contributor', label: 'Contributor' },
    { value: 'observer', label: 'Observer' },
    { value: 'approver', label: 'Approver' },
    { value: 'subject-matter-expert', label: 'Subject Matter Expert' },
  ];

  const recurringOptions = [
    { value: 'none', label: 'Does not repeat' },
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'bi-weekly', label: 'Bi-weekly' },
    { value: 'monthly', label: 'Monthly' },
  ];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle>Create New Meeting</DialogTitle>
          <DialogDescription>
            Schedule a new meeting with participants and agenda items
          </DialogDescription>
        </DialogHeader>

        <ScrollArea className="flex-1 pr-4">
          <form id="meeting-form" onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {/* Basic Info */}
            <div className="space-y-4">
              <div>
                <Label htmlFor="title">Meeting Title *</Label>
                <Input
                  id="title"
                  {...register('title')}
                  placeholder="e.g., Sprint Planning Meeting"
                  className={cn(errors.title && 'border-destructive')}
                />
                {errors.title && (
                  <p className="text-xs text-destructive mt-1">{errors.title.message}</p>
                )}
              </div>

              <div>
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  {...register('description')}
                  placeholder="Meeting purpose and context..."
                  rows={2}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Date *</Label>
                  <Popover>
                    <PopoverTrigger asChild>
                      <Button
                        variant="outline"
                        className={cn(
                          'w-full justify-start text-left font-normal',
                          !selectedDate && 'text-muted-foreground',
                          errors.date && 'border-destructive'
                        )}
                      >
                        <CalendarIcon className="mr-2 h-4 w-4" />
                        {selectedDate ? format(selectedDate, 'PPP') : 'Pick a date'}
                      </Button>
                    </PopoverTrigger>
                    <PopoverContent className="w-auto p-0" align="start">
                      <Calendar
                        mode="single"
                        selected={selectedDate}
                        onSelect={(date) => date && setValue('date', date)}
                        initialFocus
                      />
                    </PopoverContent>
                  </Popover>
                  {errors.date && (
                    <p className="text-xs text-destructive mt-1">{errors.date.message}</p>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <Label htmlFor="startTime">Start Time *</Label>
                    <Input
                      id="startTime"
                      type="time"
                      {...register('startTime')}
                      className={cn(errors.startTime && 'border-destructive')}
                    />
                  </div>
                  <div>
                    <Label htmlFor="endTime">End Time</Label>
                    <Input id="endTime" type="time" {...register('endTime')} />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Meeting Type</Label>
                  <Select
                    value={meetingType}
                    onValueChange={(value) => setValue('meetingType', value as any)}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="online">
                        <div className="flex items-center gap-2">
                          <Video className="h-4 w-4" />
                          Online
                        </div>
                      </SelectItem>
