                </TableCell>
              </TableRow>
            ) : (
              resources.map((resource) => (
                <TableRow key={resource.id}>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Input
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        className="h-8"
                      />
                    ) : (
                      <span className="font-medium">{resource.name}</span>
                    )}
                  </TableCell>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Select
                        value={formData.type}
                        onValueChange={(v) => setFormData({ ...formData, type: v as any })}
                      >
                        <SelectTrigger className="h-8 w-24">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="work">Work</SelectItem>
                          <SelectItem value="material">Material</SelectItem>
                          <SelectItem value="cost">Cost</SelectItem>
                        </SelectContent>
                      </Select>
                    ) : (
                      <Badge className={getTypeColor(resource.type)} variant="secondary">
                        {resource.type}
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Input
                        type="email"
                        value={formData.email}
                        onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                        className="h-8"
                      />
                    ) : (
                      <span className="text-muted-foreground">{resource.email || '—'}</span>
                    )}
                  </TableCell>
                  <TableCell>
                    {editingId === resource.id ? (
                      <Select
                        value={formData.calendar_id || '__default__'}
                        onValueChange={(v) =>
                          setFormData({ ...formData, calendar_id: v === '__default__' ? null : v })
                        }
                      >
                        <SelectTrigger className="h-8 w-32">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="__default__">Project Default</SelectItem>
                          {calendars.map((cal) => (
                            <SelectItem key={cal.id} value={cal.id}>
                              {cal.name}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : (
                      <div className="flex items-center gap-1.5">
                        <CalendarIcon className="h-3 w-3 text-muted-foreground" />
                        <span className="text-sm">{getCalendarName(resource.calendar_id)}</span>
                      </div>
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    {editingId === resource.id ? (
                      <Input
                        type="number"
                        step="0.1"
                        min="0"
                        value={formData.max_units}
                        onChange={(e) => setFormData({ ...formData, max_units: parseFloat(e.target.value) })}
                        className="h-8 w-20 text-right"
                      />
                    ) : (
                      `${(resource.max_units * 100).toFixed(0)}%`
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    {editingId === resource.id ? (
                      <Input
                        type="number"
                        step="0.01"
                        min="0"
                        value={formData.standard_rate}
                        onChange={(e) => setFormData({ ...formData, standard_rate: parseFloat(e.target.value) })}
                        className="h-8 w-24 text-right"
                      />
                    ) : (
                      `$${resource.standard_rate.toFixed(2)}`
