                  </TableCell>
                  <TableCell className="text-right">
                    {editingId === resource.id ? (
                      <Input
                        type="number"
                        step="0.01"
                        min="0"
                        value={formData.overtime_rate}
                        onChange={(e) => setFormData({ ...formData, overtime_rate: parseFloat(e.target.value) })}
