              </Card>

              <Card className="border-info/30">
                <CardHeader className="pb-2">
                  <CardTitle className="text-base flex items-center gap-2">
                    <TrendingDown className="h-4 w-4 text-info" />
                    Scope Creep
                  </CardTitle>
                </CardHeader>
                <CardContent>
