                  <div className="p-4 rounded-lg border bg-warning/5">
                    <div className="flex items-center gap-2 mb-2">
                      <AlertTriangle className="h-4 w-4 text-warning" />
                      <h4 className="font-medium text-sm">New Risks</h4>
