export function EnhancedMeetingsView({ demo = false }: EnhancedMeetingsViewProps) {
  const { settings } = useProjectContext();
  const projectId = settings?.id || 'demo';

  const {
    meetings: realMeetings,
    isLoading: isRealLoading,
    createMeeting,
    addParticipant,
    addAgendaItem,
    updateMeeting,
    processWithAI,
    generateMoM,
  } = useMeetings(projectId);

  const meetings = demo ? MOCK_MEETINGS as any[] : realMeetings;
  const isLoading = demo ? false : isRealLoading;

  const [selectedMeetingId, setSelectedMeetingId] = useState<string | null>(null);
  const [showMoM, setShowMoM] = useState(false);
  const [showAISidebar, setShowAISidebar] = useState(true);
  const [showMiniCalendar, setShowMiniCalendar] = useState(true);
  const [linkDialogOpen, setLinkDialogOpen] = useState(false);
  const [linkingAction, setLinkingAction] = useState<{ id: string; title: string } | null>(null);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showTranscriptDialog, setShowTranscriptDialog] = useState(false);
  const [isGeneratingMoM, setIsGeneratingMoM] = useState(false);

  // Mini calendar states
  const [calendarMonth, setCalendarMonth] = useState(new Date());
  const [filterDate, setFilterDate] = useState<Date | null>(null);

  // Edit dialog states
  const [showRecurringEditDialog, setShowRecurringEditDialog] = useState(false);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [editMode, setEditMode] = useState<'single' | 'all'>('single');
  const [meetingToEdit, setMeetingToEdit] = useState<MeetingWithRelations | null>(null);

  // Map meetings to display format
  const displayMeetings = useMemo(() => meetings.map(mapMeetingToDisplay), [meetings]);

  // Filter meetings by selected date
  const filteredMeetings = useMemo(() => {
    if (!filterDate) return displayMeetings;
    return displayMeetings.filter((m) => isSameDay(new Date(m.date), filterDate));
  }, [displayMeetings, filterDate]);

  // Generate meeting dates for mini calendar (count meetings per day)
  const meetingDates = useMemo(() => {
    const dateMap = new Map<string, number>();
    displayMeetings.forEach((m) => {
      const dateKey = new Date(m.date).toDateString();
      dateMap.set(dateKey, (dateMap.get(dateKey) || 0) + 1);
    });
    return Array.from(dateMap.entries()).map(([dateStr, count]) => ({
      date: new Date(dateStr),
      count,
    }));
  }, [displayMeetings]);

  // Get selected meeting
  const selectedMeeting = useMemo(() => {
    if (!selectedMeetingId && filteredMeetings.length > 0) {
      return filteredMeetings[0];
    }
    return filteredMeetings.find((m) => m.id === selectedMeetingId) || null;
  }, [selectedMeetingId, filteredMeetings]);

  // Auto-select first meeting
  React.useEffect(() => {
    if (filteredMeetings.length > 0 && !selectedMeetingId) {
      setSelectedMeetingId(filteredMeetings[0].id);
    }
  }, [filteredMeetings, selectedMeetingId]);

  // Handle date selection from mini calendar
  const handleDateSelect = (date: Date | null) => {
    setFilterDate(date);
    setSelectedMeetingId(null); // Reset selection when filtering
  };

  const handleOpenLinkDialog = (actionId: string, actionTitle: string) => {
    setLinkingAction({ id: actionId, title: actionTitle });
    setLinkDialogOpen(true);
  };

  const handleLinkItems = (items: LinkableItem[]) => {
    console.log('Linked items to action:', items);
  };

  const handleCreateMeeting = async (
    meeting: CreateMeetingInput,
    participants: CreateParticipantInput[],
    agendaItems: CreateAgendaItemInput[]
  ) => {
    const createdMeeting = await createMeeting(meeting);
    if (createdMeeting) {
      // Add participants
      for (const p of participants) {
        await addParticipant({ ...p, meeting_id: createdMeeting.id });
      }
      // Add agenda items
      for (const a of agendaItems) {
        await addAgendaItem({ ...a, meeting_id: createdMeeting.id });
      }
      setSelectedMeetingId(createdMeeting.id);
    }
  };

  const handleUploadTranscript = async (transcript: string) => {
    if (!selectedMeeting) return;

    await updateMeeting(selectedMeeting.id, {
      // We need to store transcript - update the meeting record
    });

    // Store transcript in the meeting
    const { error } = await supabase
      .from('meetings')
      .update({
        transcript_text: transcript,
        transcript_available: true,
        capture_mode: 'post-meeting',
      })
      .eq('id', selectedMeeting.id);

    if (error) {
      toast.error('Failed to save transcript');
      throw error;
    }
  };

  const handleProcessWithAI = async () => {
    if (!selectedMeeting) return;
    await processWithAI(selectedMeeting.id);
  };

  const handleGenerateMoM = async () => {
    if (!selectedMeeting) return;
    setIsGeneratingMoM(true);
    try {
      await generateMoM(selectedMeeting.id);
      setShowMoM(true);
    } finally {
      setIsGeneratingMoM(false);
    }
  };

  // Handle edit button click
  const handleEditClick = (meeting: ReturnType<typeof mapMeetingToDisplay>) => {
    const dbMeeting = meetings.find((m) => m.id === meeting.id);
    if (!dbMeeting) return;

    setMeetingToEdit(dbMeeting);

    // Check if this is a recurring meeting
    if (meeting.isRecurring) {
      setShowRecurringEditDialog(true);
    } else {
      setEditMode('single');
      setShowEditDialog(true);
    }
  };

  const handleEditSingle = () => {
    setEditMode('single');
    setShowEditDialog(true);
  };

  const handleEditAll = () => {
    setEditMode('all');
    setShowEditDialog(true);
  };

  const handleSaveEdit = async (id: string, updates: Record<string, unknown>) => {
    if (editMode === 'all' && meetingToEdit?.recurring_parent_id) {
      // Update all instances in the series
      const parentId = meetingToEdit.recurring_parent_id || id;

      // Update parent meeting
      await updateMeeting(parentId, updates);

      // Update all child instances (excluding date for 'all' edit)
      const { date, ...updatesWithoutDate } = updates;
      const childMeetings = meetings.filter((m) => m.recurring_parent_id === parentId);
      for (const child of childMeetings) {
        await updateMeeting(child.id, updatesWithoutDate);
      }

      toast.success(`Updated ${childMeetings.length + 1} meetings in series`);
    } else {
      // Update single instance
      await updateMeeting(id, updates);
    }

    setMeetingToEdit(null);
  };

  const getCaptureIcon = (mode: string) => {
    switch (mode) {
      case 'live-transcription':
        return <Wifi className="h-4 w-4 text-success animate-pulse" />;
      case 'post-meeting':
        return <Timer className="h-4 w-4 text-info" />;
      case 'manual-entry':
        return <FileText className="h-4 w-4 text-muted-foreground" />;
      default:
        return <WifiOff className="h-4 w-4 text-muted-foreground" />;
    }
  };

  const getSourceBadge = (source: string) => {
    const colors: Record<string, string> = {
      teams: 'bg-[#6264a7] text-white',
      zoom: 'bg-[#2d8cff] text-white',
      meet: 'bg-[#00897b] text-white',
      audio: 'bg-muted text-muted-foreground',
      manual: 'bg-muted text-muted-foreground',
    };
    return colors[source] || 'bg-muted text-muted-foreground';
  };

  const getDecisionTypeColor = (type: string) => {
    switch (type) {
