              setFormData((prev) => ({ ...prev, governanceLevel: value }))
            }
            className="grid grid-cols-1 md:grid-cols-3 gap-4"
          >
            {governanceLevels.map((level) => {
              const Icon = level.icon;
              return (
                <div key={level.id}>
                  <RadioGroupItem
                    value={level.id}
                    id={level.id}
                    className="peer sr-only"
                  />
