import { useProjectContext } from '@/contexts/ProjectContext';
import { useReports, Report, ReportCategory } from '@/hooks/useReports';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
