          <div className="flex items-center gap-1 mt-1">
            <Link2 className="h-3 w-3 text-muted-foreground" />
            <span className="text-xs text-muted-foreground">{item.linkedTo.length} links</span>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

