import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type ItemType = 'epic' | 'story' | 'task' | 'bug' | 'tech-debt';
export type BacklogStatus = 'todo' | 'in-progress' | 'review' | 'done';
export type BacklogPriority = 'critical' | 'high' | 'medium' | 'low';
export type PriorityLevel = BacklogPriority;

export interface BacklogItem { id: string; project_id: string | null; epic_id: string | null; sprint_id: string | null; key: string | null; title: string; description: string | null; type: ItemType; priority: BacklogPriority; story_points: number | null; assignee_id: string | null; assignee_name: string | null; labels: string[]; status: BacklogStatus; sort_order: number; created_at: string; updated_at: string; }
export interface BacklogItemInput { title: string; description?: string; type?: ItemType; priority?: BacklogPriority; story_points?: number; assignee_name?: string; labels?: string[]; epic_id?: string; sprint_id?: string; status?: BacklogStatus; }

export function useBacklogItems() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [items, setItems] = useState<BacklogItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchItems = useCallback(async () => {
    if (!projectId) { setItems([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('backlog_items').select('*').eq('project_id', projectId).order('sort_order', { ascending: true });
      if (e) throw e;
      setItems((data || []).map((item: any) => ({ ...item, type: item.type as ItemType, priority: item.priority as BacklogPriority, status: item.status as BacklogStatus, labels: Array.isArray(item.labels) ? item.labels : [] })));
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchItems(); }, [fetchItems]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('backlog-items-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'backlog_items', filter: `project_id=eq.${projectId}` }, () => fetchItems()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchItems]);

  const generateKey = () => `BL-${String(items.length + 1).padStart(3, '0')}`;

  const createItem = async (input: BacklogItemInput): Promise<BacklogItem | null> => {
    if (!projectId) { toast.error('No project selected'); return null; }
    try {
      const key = generateKey();
      const { data, error: e } = await supabase.from('backlog_items').insert({ project_id: projectId, key, title: input.title, description: input.description || null, type: input.type || 'story', priority: input.priority || 'medium', story_points: input.story_points || null, assignee_name: input.assignee_name || null, labels: input.labels || [], epic_id: input.epic_id || null, sprint_id: input.sprint_id || null, status: input.status || 'todo', sort_order: items.length }).select().single();
      if (e) throw e;
      const item: BacklogItem = { ...data, type: data.type as ItemType, priority: data.priority as BacklogPriority, status: data.status as BacklogStatus, labels: (Array.isArray(data.labels) ? data.labels : []).map(String), sort_order: data.sort_order ?? 0 };
      toast.success('Backlog item created'); return item;
    } catch { toast.error('Failed to create backlog item'); return null; }
  };

  const updateItem = async (id: string, updates: Partial<BacklogItemInput>) => {
    try { const { error: e } = await supabase.from('backlog_items').update(updates as any).eq('id', id); if (e) throw e; toast.success('Item updated'); return true; } catch { toast.error('Failed to update item'); return false; }
  };

  const moveToSprint = async (id: string, sprintId: string | null) => updateItem(id, { sprint_id: sprintId } as any);
  const updateStatus = async (id: string, status: BacklogStatus) => updateItem(id, { status });
  const deleteItem = async (id: string) => { try { await supabase.from('backlog_items').delete().eq('id', id); toast.success('Item deleted'); return true; } catch { toast.error('Failed'); return false; } };

  const totalPoints = items.reduce((sum, i) => sum + (i.story_points || 0), 0);
  const scheduledItems = items.filter(i => i.sprint_id);
  const unassignedItems = items.filter(i => !i.epic_id);

  return { items, loading, error, refetch: fetchItems, createItem, updateItem, moveToSprint, updateStatus, deleteItem, totalPoints, scheduledItems, unassignedItems };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from './useAuth';
import { toast } from 'sonner';
import {
  type ChatMessage,
  type DbMessage,
  type AttachmentData,
  type Reaction,
  type ReadReceipt,
  type EditHistoryEntry,
  parseMessageJsonFields,
  filterVisibleMessages,
  getPinnedMessages,
  scrollToMessage,
} from '@/components/chat/ChatEngine';

export interface UseChatEngineOptions {
  projectId: string | null;
  channelId?: string | null; // Added channelId
  onNewMessage?: (msg: ChatMessage) => void;
}

export interface UseChatEngineReturn {
  // State
  messages: ChatMessage[];
  isLoading: boolean;
  isSending: boolean;

  // Derived data
  pinnedMessages: ReturnType<typeof getPinnedMessages>;
  visibleMessages: ChatMessage[];

  // Message CRUD
  sendMessage: (
    content: string,
    attachment?: AttachmentData | null,
    replyTo?: string | null
  ) => Promise<boolean>;
  editMessage: (messageId: string, newContent: string) => Promise<boolean>;
  deleteMessage: (messageId: string) => Promise<boolean>;
  forwardMessage: (
    originalMessage: ChatMessage,
    targetProjectId: string, // Kept for logic, but might need channel target in future
    additionalText?: string
  ) => Promise<boolean>;

  // Features
  togglePin: (messageId: string, currentPinned: boolean) => Promise<void>;
  addReaction: (messageId: string, emoji: string) => Promise<void>;
  removeReaction: (messageId: string, emoji: string) => Promise<void>;
  updateReadReceipts: (messageId: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;

  // Helpers
  getParentMessage: (replyToId: string | null | undefined) => ChatMessage | undefined;
  jumpToMessage: (messageId: string, refs: Map<string, HTMLDivElement>) => void;

  // Current user
  currentUserId?: string;
}

/**
 * Core chat engine hook that encapsulates all chat business logic
 * Used by both ProjectChat (compact) and TeamChatView (full-page)
 */
export function useChatEngine({
  projectId,
  channelId,
  onNewMessage,
}: UseChatEngineOptions): UseChatEngineReturn {
  const { user } = useAuth();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const onNewMessageRef = useRef(onNewMessage);
  onNewMessageRef.current = onNewMessage;

  // Fetch initial messages
  useEffect(() => {
    // If no channelId, we might want to wait or clear. 
    // If only projectId is provided, old logic fetched by project_id.
    // New logic: fetch by channel_id.
    if (!channelId) {
      setMessages([]);
      return;
    }

    const fetchMessages = async () => {
      setIsLoading(true);
      const { data, error } = await supabase
        .from('chat_messages') // Updated table name
        .select('*')
        .eq('channel_id', channelId) // Updated filter
        .order('created_at', { ascending: true })
        .limit(100);

      if (error) {
        console.error('Error fetching messages:', error);
      } else {
        const parsedMessages = (data || []).map((msg) =>
          parseMessageJsonFields(msg as any) // Type assertion might be needed if types aren't regenerated yet
        );
        setMessages(parsedMessages);
      }
      setIsLoading(false);
    };

    fetchMessages();
  }, [channelId]); // Depend on channelId

  // Subscribe to realtime messages
  useEffect(() => {
    if (!channelId) return;

    const channel = supabase
      .channel(`chat_engine:${channelId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'chat_messages',
          filter: `channel_id=eq.${channelId}`,
        },
        (payload) => {
          const newMsg = parseMessageJsonFields(payload.new as any);
          setMessages((prev) => [...prev, newMsg]);
          onNewMessageRef.current?.(newMsg);
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'chat_messages',
          filter: `channel_id=eq.${channelId}`,
        },
        (payload) => {
          const updatedMsg = parseMessageJsonFields(payload.new as any);
          setMessages((prev) =>
            prev.map((m) => (m.id === updatedMsg.id ? updatedMsg : m))
          );
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'public',
          table: 'chat_messages',
          filter: `channel_id=eq.${channelId}`,
        },
        (payload) => {
          setMessages((prev) => prev.filter((m) => m.id !== (payload.old as any).id));
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [channelId]);

  // Send a new message
  const sendMessage = useCallback(
    async (
      content: string,
      attachment?: AttachmentData | null,
      replyTo?: string | null
    ): Promise<boolean> => {
      if ((!content.trim() && !attachment) || !user || !channelId) return false;

      setIsSending(true);
      const { error } = await supabase.from('chat_messages').insert({
        channel_id: channelId, // Use channelId
        user_id: user.id,
        user_email: user.email || 'Unknown',
        content: content.trim(),
        attachment_url: attachment?.url || null,
        attachment_name: attachment?.name || null,
        attachment_type: attachment?.type || null,
        attachment_size: attachment?.size || null,
        reply_to: replyTo || null,
      });

      setIsSending(false);

      if (error) {
        console.error('Error sending message:', error);
        toast.error('Failed to send message');
        return false;
      }

      return true;
    },
    [user, channelId]
  );

  // Edit an existing message
  const editMessage = useCallback(
    async (messageId: string, newContent: string): Promise<boolean> => {
      const message = messages.find((m) => m.id === messageId);
      if (!message || !user) return false;

      const newHistoryEntry: EditHistoryEntry = {
        content: message.content,
        editedAt: new Date().toISOString(),
      };

      const updatedHistory = [...(message.edit_history || []), newHistoryEntry];

      const { error } = await supabase
        .from('chat_messages')
        .update({
          content: newContent,
          edited_at: new Date().toISOString(),
          edit_history: JSON.parse(JSON.stringify(updatedHistory)),
        })
        .eq('id', messageId);

      if (error) {
        toast.error('Failed to edit message');
        return false;
      }

      toast.success('Message edited');
      return true;
    },
    [messages, user]
  );

  // Delete a message (soft delete)
  const deleteMessage = useCallback(async (messageId: string): Promise<boolean> => {
    const { error } = await supabase
      .from('chat_messages')
      .update({
        is_deleted: true,
        deleted_at: new Date().toISOString(),
        content: '[This message has been deleted]',
      })
      .eq('id', messageId);

    if (error) {
      toast.error('Failed to delete message');
      return false;
    }

    toast.success('Message deleted');
    return true;
  }, []);

  // Forward a message to another project (Adaptation: targetProjectId logic needs review if we forward to channel)
  // For now we assume we forward to a 'general' channel in the target project or we need targetChannelId
  // I will keep it but warn it might fail if table expects channel_id. 
  // IMPORTANT: The table chat_messages needs channel_id. So forwarding to a project_id doesn't make sense unless we resolve a channel.
  // I will disable forwarding for now or simplistic implementation.
  const forwardMessage = useCallback(
    async (
      originalMessage: ChatMessage,
      targetProjectId: string,
      additionalText?: string
    ): Promise<boolean> => {
      // TODO: Forward needs target Channel ID, not Project ID. 
      // For now, flagging as not implemented to avoid SQL error
      toast.error("Forwarding not fully implemented for new channel architecture");
      return false;
    },
    [user]
  );

  // Toggle pin status
  const togglePin = useCallback(
    async (messageId: string, currentPinned: boolean): Promise<void> => {
      if (!user) return;

      const { error } = await supabase
        .from('chat_messages')
        .update({
          is_pinned: !currentPinned,
          pinned_at: !currentPinned ? new Date().toISOString() : null,
          pinned_by: !currentPinned ? user.id : null,
        })
        .eq('id', messageId);

      if (error) {
        toast.error('Failed to pin message');
      } else {
        toast.success(currentPinned ? 'Message unpinned' : 'Message pinned');
      }
    },
    [user]
  );

  // Add a reaction
  const addReaction = useCallback(
    async (messageId: string, emoji: string): Promise<void> => {
      if (!user) return;

      const message = messages.find((m) => m.id === messageId);
      if (!message) return;

      const currentReactions: Reaction[] = message.reactions || [];
      const existingReaction = currentReactions.find((r) => r.emoji === emoji);

      let newReactions: Reaction[];
      if (existingReaction) {
        const alreadyReacted = existingReaction.users.some((u) => u.id === user.id);
        if (alreadyReacted) return;

        newReactions = currentReactions.map((r) =>
          r.emoji === emoji
            ? { ...r, users: [...r.users, { id: user.id, email: user.email || '' }] }
            : r
        );
      } else {
        newReactions = [
          ...currentReactions,
          { emoji, users: [{ id: user.id, email: user.email || '' }] },
        ];
      }

      await supabase
        .from('chat_messages')
        .update({ reactions: JSON.parse(JSON.stringify(newReactions)) })
        .eq('id', messageId);
    },
    [messages, user]
  );

  // Remove a reaction
  const removeReaction = useCallback(
    async (messageId: string, emoji: string): Promise<void> => {
      if (!user) return;

      const message = messages.find((m) => m.id === messageId);
      if (!message) return;

      const currentReactions: Reaction[] = message.reactions || [];
      const newReactions = currentReactions
        .map((r) =>
          r.emoji === emoji ? { ...r, users: r.users.filter((u) => u.id !== user.id) } : r
        )
        .filter((r) => r.users.length > 0);

      await supabase
        .from('chat_messages')
        .update({ reactions: JSON.parse(JSON.stringify(newReactions)) })
        .eq('id', messageId);
    },
    [messages, user]
  );

  // Update read receipts for a single message
  const updateReadReceipts = useCallback(
    async (messageId: string): Promise<void> => {
      if (!user) return;

      const message = messages.find((m) => m.id === messageId);
      if (!message) return;

      const currentReceipts: ReadReceipt[] = message.read_by || [];
      if (currentReceipts.some((r) => r.userId === user.id)) return;

      const newReceipts = [
        ...currentReceipts,
        { userId: user.id, userEmail: user.email || '', readAt: new Date().toISOString() },
      ];

      await supabase
        .from('chat_messages')
        .update({ read_by: JSON.parse(JSON.stringify(newReceipts)) })
        .eq('id', messageId);
    },
    [messages, user]
  );

  // Mark all messages as read
  const markAllAsRead = useCallback(async (): Promise<void> => {
    if (!user) return;

    const unreadMessages = messages.filter(
      (m) =>
        m.user_id !== user.id && !(m.read_by || []).some((r) => r.userId === user.id)
    );

    for (const msg of unreadMessages) {
      await updateReadReceipts(msg.id);
    }
  }, [messages, user, updateReadReceipts]);

  // Get parent message for replies
  const getParentMessage = useCallback(
    (replyToId: string | null | undefined): ChatMessage | undefined => {
      if (!replyToId) return undefined;
      return messages.find((m) => m.id === replyToId);
    },
    [messages]
  );

  // Jump to a message
  const jumpToMessage = useCallback(
    (messageId: string, refs: Map<string, HTMLDivElement>): void => {
      scrollToMessage(messageId, refs);
    },
    []
  );

  // Derived data
  const visibleMessages = filterVisibleMessages(messages);
  const pinnedMessages = getPinnedMessages(messages);

  return {
    messages,
    isLoading,
    isSending,
    pinnedMessages,
    visibleMessages,
    sendMessage,
    editMessage,
    deleteMessage,
    forwardMessage,
    togglePin,
    addReaction,
    removeReaction,
    updateReadReceipts,
    markAllAsRead,
    getParentMessage,
    jumpToMessage,
    currentUserId: user?.id,
  };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from './useAuth';

interface TypingUser {
  id: string;
  email: string;
  displayName?: string;
}

export function useChatPresence(projectId: string | null) {
  const { user } = useAuth();
  const [typingUsers, setTypingUsers] = useState<TypingUser[]>([]);
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const isTypingRef = useRef(false);

  useEffect(() => {
    if (!projectId || !user) return;

    const channel = supabase.channel(`chat-typing:${projectId}`, {
      config: { presence: { key: user.id } },
    });

    channel
      .on('presence', { event: 'sync' }, () => {
        const state = channel.presenceState();
        const users: TypingUser[] = [];

        Object.entries(state).forEach(([userId, presences]) => {
          const presence = (presences as any[])[0];
          if (presence?.isTyping) {
            users.push({
              id: userId,
              email: presence.email || 'Unknown',
              displayName: presence.displayName,
            });
          }
        });

        setTypingUsers(users);
      })
      .subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          await channel.track({
            email: user.email,
            displayName: user.email?.split('@')[0],
            isTyping: false,
          });
        }
      });

    channelRef.current = channel;

    return () => {
      channel.unsubscribe();
      channelRef.current = null;
    };
  }, [projectId, user]);

  const setTyping = useCallback(async (isTyping: boolean) => {
    if (!channelRef.current || !user) return;

    // Avoid redundant updates
    if (isTypingRef.current === isTyping) return;
    isTypingRef.current = isTyping;

    await channelRef.current.track({
      email: user.email,
      displayName: user.email?.split('@')[0],
      isTyping,
    });
  }, [user]);

  const startTyping = useCallback(() => {
    // Clear existing timeout
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }

    setTyping(true);

    // Auto-stop typing after 3 seconds of inactivity
    typingTimeoutRef.current = setTimeout(() => {
      setTyping(false);
    }, 3000);
  }, [setTyping]);

  const stopTyping = useCallback(() => {
    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }
    setTyping(false);
  }, [setTyping]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (typingTimeoutRef.current) {
        clearTimeout(typingTimeoutRef.current);
      }
    };
  }, []);

  return {
    typingUsers,
    startTyping,
    stopTyping,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type DecisionStatus = 'pending' | 'active' | 'superseded' | 'rejected';

export interface Decision {
  id: string;
  project_id: string | null;
  key: string | null;
  title: string;
  decision: string;
  context: string | null;
  impact: string | null;
  alternatives: string[];
  status: DecisionStatus;
  owner_id: string | null;
  owner_name: string | null;
  date: string;
  linked_tasks: string[];
  linked_risks: string[];
  linked_meetings: string[];
  linked_items: any[];
  tags: string[];
  created_at: string;
  updated_at: string;
}

export interface DecisionInput {
  title: string;
  decision: string;
  context?: string;
  impact?: string;
  alternatives?: string[];
  status?: DecisionStatus;
  owner_name?: string;
  date?: string;
  linked_tasks?: string[];
  linked_risks?: string[];
  linked_meetings?: string[];
  tags?: string[];
}

export function useDecisions() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [decisions, setDecisions] = useState<Decision[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchDecisions = useCallback(async () => {
    if (!projectId) {
      setDecisions([]);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      const { data, error: fetchError } = await supabase
        .from('decisions')
        .select('*')
        .eq('project_id', projectId)
        .order('created_at', { ascending: false });

      if (fetchError) throw fetchError;

      setDecisions(
        (data || []).map((d: any) => ({
          ...d,
          status: d.status as DecisionStatus,
          alternatives: Array.isArray(d.alternatives) ? d.alternatives.map(String) : [],
          linked_tasks: Array.isArray(d.linked_tasks) ? d.linked_tasks.map(String) : [],
          linked_risks: Array.isArray(d.linked_risks) ? d.linked_risks.map(String) : [],
          linked_meetings: Array.isArray(d.linked_meetings) ? d.linked_meetings.map(String) : [],
          linked_items: Array.isArray(d.linked_items) ? d.linked_items : [],
          tags: Array.isArray(d.tags) ? d.tags.map(String) : [],
        }))
      );
      setError(null);
    } catch (err: any) {
      console.error('Error fetching decisions:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  useEffect(() => {
    fetchDecisions();
  }, [fetchDecisions]);

  // Real-time subscription
  useEffect(() => {
    if (!projectId) return;

    const channel = supabase
      .channel('decisions-changes')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'decisions',
          filter: `project_id=eq.${projectId}`,
        },
        () => fetchDecisions()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [projectId, fetchDecisions]);

  const generateKey = () => {
    const count = decisions.length + 1;
    return `DEC-${String(count).padStart(3, '0')}`;
  };

  const createDecision = async (input: DecisionInput): Promise<Decision | null> => {
    if (!projectId) {
      toast.error('No project selected');
      return null;
    }

    try {
      const key = generateKey();
      const { data, error: insertError } = await supabase
        .from('decisions')
        .insert({
          project_id: projectId,
          key,
          title: input.title,
          decision: input.decision,
          context: input.context || null,
          impact: input.impact || null,
          alternatives: input.alternatives || [],
          status: input.status || 'pending',
          owner_name: input.owner_name || null,
          date: input.date || new Date().toISOString().split('T')[0],
          linked_tasks: input.linked_tasks || [],
          linked_risks: input.linked_risks || [],
          linked_meetings: input.linked_meetings || [],
          tags: input.tags || [],
        } as any)
        .select()
        .single();

      if (insertError) throw insertError;

      const decision: Decision = {
        ...data,
        status: data.status as DecisionStatus,
        alternatives: Array.isArray(data.alternatives) ? data.alternatives.map(String) : [],
        linked_tasks: Array.isArray(data.linked_tasks) ? data.linked_tasks.map(String) : [],
        linked_risks: Array.isArray(data.linked_risks) ? data.linked_risks.map(String) : [],
        linked_meetings: Array.isArray(data.linked_meetings) ? data.linked_meetings.map(String) : [],
        linked_items: Array.isArray(data.linked_items) ? data.linked_items : [],
        tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
      };

      toast.success('Decision created');
      return decision;
    } catch (err: any) {
      console.error('Error creating decision:', err);
      toast.error('Failed to create decision');
      return null;
    }
  };

  const updateDecision = async (
    id: string,
    updates: Partial<DecisionInput>
  ): Promise<boolean> => {
    try {
      const { error: updateError } = await supabase
        .from('decisions')
        .update(updates as any)
        .eq('id', id);

      if (updateError) throw updateError;

      toast.success('Decision updated');
      return true;
    } catch (err: any) {
      console.error('Error updating decision:', err);
      toast.error('Failed to update decision');
      return false;
    }
  };

  const deleteDecision = async (id: string): Promise<boolean> => {
    try {
      const { error: deleteError } = await supabase
        .from('decisions')
        .delete()
        .eq('id', id);

      if (deleteError) throw deleteError;

      toast.success('Decision deleted');
      return true;
    } catch (err: any) {
      console.error('Error deleting decision:', err);
      toast.error('Failed to delete decision');
      return false;
    }
  };

  const activeDecisions = decisions.filter((d) => d.status === 'active');
  const pendingDecisions = decisions.filter((d) => d.status === 'pending');
  const supersededDecisions = decisions.filter((d) => d.status === 'superseded');

  return {
    decisions,
    loading,
    error,
    refetch: fetchDecisions,
    createDecision,
    updateDecision,
    deleteDecision,
    activeDecisions,
    pendingDecisions,
    supersededDecisions,
  };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

export interface Deliverable {
    id: string;
    project_id: string;
    name: string;
    description: string | null;
    phase: string | null;
    type: 'document' | 'system' | 'process' | 'training' | 'other' | null;
    status: 'not-started' | 'in-progress' | 'review' | 'approved' | 'rejected';
    owner_id: string | null;
    due_date: string | null;
    completed_date: string | null;
    progress: number;
    acceptance_criteria: { text: string; met: boolean }[];
    created_at: string;
    updated_at: string;
    owner?: {
        full_name: string | null;
        avatar_url: string | null;
    } | null;
}

export function useDeliverables(projectId: string | null) {
    const queryClient = useQueryClient();

    const query = useQuery({
        queryKey: ['deliverables', projectId],
        queryFn: async () => {
            if (!projectId) return [];

            const { data, error } = await supabase
                .from('deliverables')
                .select(`
          *,
          owner:owner_id(full_name, avatar_url)
        `)
                .eq('project_id', projectId)
                .order('due_date', { ascending: true });

            if (error) {
                toast.error('Failed to fetch deliverables');
                throw error;
            }

            // Parse acceptance_criteria if it's a string (backwards compatibility or weird supabase behavior)
            // Otherwise cast it
            return data.map(d => ({
                ...d,
                acceptance_criteria: typeof d.acceptance_criteria === 'string'
                    ? JSON.parse(d.acceptance_criteria)
                    : (d.acceptance_criteria as any[] || [])
            })) as (Deliverable & { owner: { full_name: string | null, avatar_url: string | null } | null })[];
        },
        enabled: !!projectId,
    });

    const createDeliverable = useMutation({
        mutationFn: async (newDeliverable: Partial<Deliverable>) => {
            if (!projectId) throw new Error('Project ID is required');

            const { data, error } = await supabase
                .from('deliverables')
                .insert([{ ...newDeliverable, project_id: projectId }])
                .select()
                .single();

            if (error) throw error;
            return data;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['deliverables', projectId] });
            toast.success('Deliverable created successfully');
        },
        onError: (error) => {
            toast.error(`Failed to create deliverable: ${error.message}`);
        },
    });

    const updateDeliverable = useMutation({
        mutationFn: async ({ id, updates }: { id: string; updates: Partial<Deliverable> }) => {
            const { data, error } = await supabase
                .from('deliverables')
                .update(updates)
                .eq('id', id)
                .select()
                .single();

            if (error) throw error;
            return data;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['deliverables', projectId] });
            toast.success('Deliverable updated successfully');
        },
        onError: (error) => {
            toast.error(`Failed to update deliverable: ${error.message}`);
        },
    });

    const deleteDeliverable = useMutation({
        mutationFn: async (id: string) => {
            const { error } = await supabase
                .from('deliverables')
                .delete()
                .eq('id', id);

            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['deliverables', projectId] });
            toast.success('Deliverable deleted successfully');
        },
        onError: (error) => {
            toast.error(`Failed to delete deliverable: ${error.message}`);
        },
    });

    return {
        ...query,
        createDeliverable,
        updateDeliverable,
        deleteDeliverable,
    };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from './useAuth';
import { toast } from 'sonner';

export interface EmailAccount {
  id: string;
  user_id: string | null;
  project_id: string | null;
  account_type: 'personal' | 'shared';
  email_address: string;
  display_name: string | null;
  imap_host: string;
  imap_port: number;
  imap_username: string;
  imap_encryption: 'ssl' | 'tls' | 'none';
  smtp_host: string | null;
  smtp_port: number | null;
  smtp_username: string | null;
  smtp_encryption: 'ssl' | 'tls' | 'none' | null;
  is_active: boolean;
  last_sync_at: string | null;
  sync_status: 'pending' | 'syncing' | 'success' | 'error';
  sync_error: string | null;
  created_at: string;
  updated_at: string;
}

export interface CreateEmailAccountInput {
  account_type: 'personal' | 'shared';
  email_address: string;
  display_name?: string;
  imap_host: string;
  imap_port: number;
  imap_username: string;
  imap_password: string;
  imap_encryption: 'ssl' | 'tls' | 'none';
  smtp_host?: string;
  smtp_port?: number;
  smtp_username?: string;
  smtp_password?: string;
  smtp_encryption?: 'ssl' | 'tls' | 'none';
  project_id?: string;
}

export function useEmailAccounts(projectId?: string | null) {
  const { user } = useAuth();
  const [accounts, setAccounts] = useState<EmailAccount[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchAccounts = useCallback(async () => {
    if (!user) return;

    setIsLoading(true);
    setError(null);

    try {
      let query = supabase
        .from('email_accounts')
        .select('*')
        .order('created_at', { ascending: false });

      // Get personal accounts for the user + shared accounts for the project
      if (projectId) {
        query = query.or(`user_id.eq.${user.id},project_id.eq.${projectId}`);
      } else {
        query = query.eq('user_id', user.id);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;
      setAccounts((data as EmailAccount[]) || []);
    } catch (err) {
      console.error('Error fetching email accounts:', err);
      setError('Failed to load email accounts');
    } finally {
      setIsLoading(false);
    }
  }, [user, projectId]);

  useEffect(() => {
    fetchAccounts();
  }, [fetchAccounts]);

  const createAccount = useCallback(
    async (input: CreateEmailAccountInput): Promise<EmailAccount | null> => {
      if (!user) {
        toast.error('You must be logged in');
        return null;
      }

      try {
        const { data, error: insertError } = await supabase
          .from('email_accounts')
          .insert({
            ...input,
            user_id: input.account_type === 'personal' ? user.id : null,
            project_id: input.account_type === 'shared' ? input.project_id : null,
          })
          .select()
          .single();

        if (insertError) throw insertError;

        toast.success('Email account added successfully');
        fetchAccounts();
        return data as EmailAccount;
      } catch (err: any) {
        console.error('Error creating email account:', err);
        toast.error(err.message || 'Failed to add email account');
        return null;
      }
    },
    [user, fetchAccounts]
  );

  const updateAccount = useCallback(
    async (id: string, updates: Partial<CreateEmailAccountInput>): Promise<boolean> => {
      try {
        const { error: updateError } = await supabase
          .from('email_accounts')
          .update(updates)
          .eq('id', id);

        if (updateError) throw updateError;

        toast.success('Email account updated');
        fetchAccounts();
        return true;
      } catch (err) {
        console.error('Error updating email account:', err);
        toast.error('Failed to update email account');
        return false;
      }
    },
    [fetchAccounts]
  );

  const deleteAccount = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        const { error: deleteError } = await supabase
          .from('email_accounts')
          .delete()
          .eq('id', id);

        if (deleteError) throw deleteError;

        toast.success('Email account removed');
        fetchAccounts();
        return true;
      } catch (err) {
        console.error('Error deleting email account:', err);
        toast.error('Failed to remove email account');
        return false;
      }
    },
    [fetchAccounts]
  );

  const syncAccount = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        // Get account to determine provider type
        const account = accounts.find((a) => a.id === id);
        if (!account) {
          throw new Error('Account not found');
        }

        // Update status to syncing
        await supabase
          .from('email_accounts')
          .update({ sync_status: 'syncing' })
          .eq('id', id);

        // Determine which sync function to call based on provider type
        const providerType = (account as any).provider_type || 'imap';
        let functionName = 'email-sync';

        if (providerType === 'gmail') {
          functionName = 'gmail-sync';
        } else if (providerType === 'microsoft') {
          functionName = 'microsoft-sync';
        }

        // Call the appropriate sync edge function
        const response = await supabase.functions.invoke(functionName, {
          body: { accountId: id },
        });

        if (response.error) throw response.error;

        toast.success('Email sync started');
        fetchAccounts();
        return true;
      } catch (err) {
        console.error('Error syncing email account:', err);
        toast.error('Failed to sync emails');
        return false;
      }
    },
    [accounts, fetchAccounts]
  );

  const testConnection = useCallback(
    async (input: CreateEmailAccountInput): Promise<{ success: boolean; error?: string }> => {
      try {
        const response = await supabase.functions.invoke('email-test-connection', {
          body: input,
        });

        if (response.error) throw response.error;

        return { success: true };
      } catch (err: any) {
        return { success: false, error: err.message || 'Connection failed' };
      }
    },
    []
  );

  return {
    accounts,
    isLoading,
    error,
    fetchAccounts,
    createAccount,
    updateAccount,
    deleteAccount,
    syncAccount,
    testConnection,
  };
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from './useAuth';
import { toast } from 'sonner';

export interface Email {
  id: string;
  account_id: string;
  folder_id: string;
  message_id: string;
  thread_id: string | null;
  in_reply_to: string | null;
  references_ids: string[];
  subject: string | null;
  from_address: string;
  from_name: string | null;
  to_addresses: { email: string; name?: string }[];
  cc_addresses: { email: string; name?: string }[];
  bcc_addresses: { email: string; name?: string }[];
  reply_to: string | null;
  body_text: string | null;
  body_html: string | null;
  snippet: string | null;
  has_attachments: boolean;
  attachments: { name: string; size: number; type: string; url?: string }[];
  is_read: boolean;
  is_starred: boolean;
  is_flagged: boolean;
  labels: string[];
  sent_at: string | null;
  received_at: string;
  created_at: string;
}

export interface EmailFolder {
  id: string;
  account_id: string;
  name: string;
  remote_name: string;
  folder_type: 'inbox' | 'sent' | 'drafts' | 'trash' | 'spam' | 'archive' | 'custom';
  unread_count: number;
  total_count: number;
  created_at: string;
}

export interface EmailThread {
  thread_id: string;
  subject: string;
  participants: string[];
  emails: Email[];
  unread_count: number;
  last_email_at: string;
}

export function useEmails(accountIds: string[]) {
  const { user } = useAuth();
  const [emails, setEmails] = useState<Email[]>([]);
  const [folders, setFolders] = useState<EmailFolder[]>([]);
  const [selectedFolderId, setSelectedFolderId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch folders for all accounts
  const fetchFolders = useCallback(async () => {
    if (accountIds.length === 0) return;

    try {
      const { data, error: fetchError } = await supabase
        .from('email_folders')
        .select('*')
        .in('account_id', accountIds)
        .order('folder_type', { ascending: true });

      if (fetchError) throw fetchError;
      setFolders((data as EmailFolder[]) || []);

      // Auto-select inbox if not selected
      if (!selectedFolderId && data && data.length > 0) {
        const inbox = data.find((f: any) => f.folder_type === 'inbox');
        if (inbox) setSelectedFolderId(inbox.id);
      }
    } catch (err) {
      console.error('Error fetching folders:', err);
    }
  }, [accountIds, selectedFolderId]);

  // Fetch emails for selected folder
  const fetchEmails = useCallback(async () => {
    if (accountIds.length === 0) return;

    setIsLoading(true);
    setError(null);

    try {
      let query = supabase
        .from('emails')
        .select('*')
        .in('account_id', accountIds)
        .order('received_at', { ascending: false })
        .limit(100);

      if (selectedFolderId) {
        query = query.eq('folder_id', selectedFolderId);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;
      setEmails((data as Email[]) || []);
    } catch (err) {
      console.error('Error fetching emails:', err);
      setError('Failed to load emails');
    } finally {
      setIsLoading(false);
    }
  }, [accountIds, selectedFolderId]);

  useEffect(() => {
    fetchFolders();
  }, [fetchFolders]);

  useEffect(() => {
    fetchEmails();
  }, [fetchEmails]);

  // Realtime subscription
  useEffect(() => {
    if (accountIds.length === 0) return;

    const channel = supabase
      .channel('emails_changes')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'emails' },
        () => fetchEmails()
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [accountIds, fetchEmails]);

  // Group emails by thread
  const threads = useMemo((): EmailThread[] => {
    const threadMap = new Map<string, Email[]>();

    emails.forEach((email) => {
      const threadId = email.thread_id || email.message_id;
      const existing = threadMap.get(threadId) || [];
      existing.push(email);
      threadMap.set(threadId, existing);
    });

    return Array.from(threadMap.entries()).map(([threadId, threadEmails]) => {
      const sortedEmails = threadEmails.sort(
        (a, b) => new Date(a.received_at).getTime() - new Date(b.received_at).getTime()
      );
      const lastEmail = sortedEmails[sortedEmails.length - 1];
      const participants = [...new Set(threadEmails.map((e) => e.from_address))];
      const unreadCount = threadEmails.filter((e) => !e.is_read).length;

      return {
        thread_id: threadId,
        subject: lastEmail.subject || '(No subject)',
        participants,
        emails: sortedEmails,
        unread_count: unreadCount,
        last_email_at: lastEmail.received_at,
      };
    }).sort((a, b) => new Date(b.last_email_at).getTime() - new Date(a.last_email_at).getTime());
  }, [emails]);

  // Mark email as read
  const markAsRead = useCallback(
    async (id: string, isRead: boolean = true): Promise<boolean> => {
      try {
        const { error: updateError } = await supabase
          .from('emails')
          .update({ is_read: isRead })
          .eq('id', id);

        if (updateError) throw updateError;
        fetchEmails();
        return true;
      } catch (err) {
        console.error('Error updating email:', err);
        return false;
      }
    },
    [fetchEmails]
  );

  // Toggle star
  const toggleStar = useCallback(
    async (id: string): Promise<boolean> => {
      const email = emails.find((e) => e.id === id);
      if (!email) return false;

      try {
        const { error: updateError } = await supabase
          .from('emails')
          .update({ is_starred: !email.is_starred })
          .eq('id', id);

        if (updateError) throw updateError;
        fetchEmails();
        return true;
      } catch (err) {
        console.error('Error updating email:', err);
        return false;
      }
    },
    [emails, fetchEmails]
  );

  // Move to folder
  const moveToFolder = useCallback(
    async (emailId: string, folderId: string): Promise<boolean> => {
      try {
        const { error: updateError } = await supabase
          .from('emails')
          .update({ folder_id: folderId })
          .eq('id', emailId);

        if (updateError) throw updateError;
        toast.success('Email moved');
        fetchEmails();
        return true;
      } catch (err) {
        console.error('Error moving email:', err);
        toast.error('Failed to move email');
        return false;
      }
    },
    [fetchEmails]
  );

  // Delete email (move to trash or permanent delete)
  const deleteEmail = useCallback(
    async (id: string): Promise<boolean> => {
      try {
        // Find trash folder
        const trashFolder = folders.find((f) => f.folder_type === 'trash');

        if (trashFolder) {
          // Move to trash
          return await moveToFolder(id, trashFolder.id);
        } else {
          // Permanent delete
          const { error: deleteError } = await supabase
            .from('emails')
            .delete()
            .eq('id', id);

          if (deleteError) throw deleteError;
          toast.success('Email deleted');
          fetchEmails();
          return true;
        }
      } catch (err) {
        console.error('Error deleting email:', err);
        toast.error('Failed to delete email');
        return false;
      }
    },
    [folders, moveToFolder, fetchEmails]
  );

  // Get unread count
  const unreadCount = useMemo(() => {
    return emails.filter((e) => !e.is_read).length;
  }, [emails]);

  return {
    emails,
    folders,
    threads,
    selectedFolderId,
    setSelectedFolderId,
    isLoading,
    error,
    unreadCount,
    fetchEmails,
    fetchFolders,
    markAsRead,
    toggleStar,
    moveToFolder,
    deleteEmail,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export interface Epic {
  id: string;
  project_id: string | null;
  name: string;
  color: string;
  description: string | null;
  progress: number;
  total_points: number;
  completed_points: number;
  sort_order: number;
  created_at: string;
  updated_at: string;
}

export interface EpicInput {
  name: string;
  color?: string;
  description?: string;
}

export function useEpics() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [epics, setEpics] = useState<Epic[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchEpics = useCallback(async () => {
    if (!projectId) { setEpics([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('epics').select('*').eq('project_id', projectId).order('sort_order', { ascending: true });
      if (e) throw e;
      setEpics(data || []);
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchEpics(); }, [fetchEpics]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('epics-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'epics', filter: `project_id=eq.${projectId}` }, () => fetchEpics()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchEpics]);

  const createEpic = async (input: EpicInput) => {
