  };

  return { epics, loading, error, refetch: fetchEpics, createEpic, updateEpic, deleteEpic };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type IssueSeverity = 'minor' | 'moderate' | 'major' | 'critical' | 'high' | 'medium' | 'low';
export type IssueStatus = 'open' | 'investigating' | 'in-progress' | 'blocked' | 'resolved' | 'closed';
export type IssuePriority = 'critical' | 'high' | 'medium' | 'low';
export type IssueType = 'bug' | 'blocker' | 'impediment' | 'defect' | 'incident';

export interface Issue { id: string; project_id: string | null; key: string | null; title: string; description: string | null; type: string; severity: IssueSeverity; priority: IssuePriority; status: IssueStatus; reporter_id: string | null; reporter_name: string | null; assignee_id: string | null; assignee_name: string | null; sla_target_resolution: number | null; sla_breached: boolean; linked_items: any[]; affected_areas: string[]; tags: string[]; root_cause: string | null; resolution: string | null; comments: any[]; history: any[]; created_at: string; updated_at: string; resolved_at: string | null; closed_at: string | null; }
export interface IssueInput { title: string; description?: string; type?: string; severity?: IssueSeverity; priority?: IssuePriority; status?: IssueStatus; reporter_name?: string; assignee_name?: string; sla_target_resolution?: number; affected_areas?: string[]; tags?: string[]; }

export function useIssues() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [issues, setIssues] = useState<Issue[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchIssues = useCallback(async () => {
    if (!projectId) { setIssues([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('issues').select('*').eq('project_id', projectId).order('created_at', { ascending: false });
      if (e) throw e;
      setIssues((data || []).map((i: any) => ({ ...i, severity: i.severity as IssueSeverity, priority: i.priority as IssuePriority, status: i.status as IssueStatus, linked_items: Array.isArray(i.linked_items) ? i.linked_items : [], affected_areas: Array.isArray(i.affected_areas) ? i.affected_areas : [], tags: Array.isArray(i.tags) ? i.tags : [], comments: Array.isArray(i.comments) ? i.comments : [], history: Array.isArray(i.history) ? i.history : [] })));
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchIssues(); }, [fetchIssues]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('issues-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'issues', filter: `project_id=eq.${projectId}` }, () => fetchIssues()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchIssues]);

  const generateKey = () => `ISS-${String(issues.length + 1).padStart(3, '0')}`;

  const createIssue = async (input: IssueInput): Promise<Issue | null> => {
    if (!projectId) { toast.error('No project selected'); return null; }
    try {
      const key = generateKey();
      const { data, error: e } = await supabase.from('issues').insert({ project_id: projectId, key, title: input.title, description: input.description || null, type: input.type || 'bug', severity: input.severity || 'moderate', priority: input.priority || 'medium', status: input.status || 'open', reporter_name: input.reporter_name || null, assignee_name: input.assignee_name || null, sla_target_resolution: input.sla_target_resolution || null, affected_areas: input.affected_areas || [], tags: input.tags || [], history: [{ timestamp: new Date().toISOString(), user: input.reporter_name || 'System', action: 'Created issue' }] } as any).select().single();
      if (e) throw e;
      const issue: Issue = { ...data, severity: data.severity as IssueSeverity, priority: data.priority as IssuePriority, status: data.status as IssueStatus, linked_items: Array.isArray(data.linked_items) ? data.linked_items : [], affected_areas: (Array.isArray(data.affected_areas) ? data.affected_areas : []).map(String), tags: (Array.isArray(data.tags) ? data.tags : []).map(String), comments: Array.isArray(data.comments) ? data.comments : [], history: Array.isArray(data.history) ? data.history : [] };
      toast.success('Issue created'); return issue;
    } catch { toast.error('Failed to create issue'); return null; }
  };

  const updateIssue = async (id: string, updates: Partial<IssueInput & { root_cause?: string; resolution?: string }>) => {
    try {
      const issue = issues.find(i => i.id === id);
      const updateData: any = { ...updates };
      if (updates.status === 'resolved' && issue?.status !== 'resolved') updateData.resolved_at = new Date().toISOString();
      if (updates.status === 'closed' && issue?.status !== 'closed') updateData.closed_at = new Date().toISOString();
      const { error: e } = await supabase.from('issues').update(updateData).eq('id', id);
      if (e) throw e; toast.success('Issue updated'); return true;
    } catch { toast.error('Failed to update issue'); return false; }
  };

  const addComment = async (id: string, user: string, text: string) => {
    const issue = issues.find(i => i.id === id);
    if (!issue) return false;
    const newComment = { id: crypto.randomUUID(), user, text, timestamp: new Date().toISOString() };
    try {
      const { error: e } = await supabase.from('issues').update({ comments: [...issue.comments, newComment] }).eq('id', id);
      if (e) throw e; return true;
    } catch { return false; }
  };

  const deleteIssue = async (id: string) => { try { await supabase.from('issues').delete().eq('id', id); toast.success('Issue deleted'); return true; } catch { toast.error('Failed'); return false; } };

  const openIssues = issues.filter(i => i.status === 'open');
  const criticalIssues = issues.filter(i => i.severity === 'critical' || i.priority === 'critical');
  const slaBreachedIssues = issues.filter(i => i.sla_breached);

  return { issues, loading, error, refetch: fetchIssues, createIssue, updateIssue, deleteIssue, addComment, openIssues, criticalIssues, slaBreachedIssues };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

export type ReportType = 'status' | 'financial' | 'resource' | 'risk' | 'custom';
export type ReportCategory = 'Status' | 'Financial' | 'Resource' | 'Risk' | 'Custom';
export type ReportFrequency = 'daily' | 'weekly' | 'monthly' | 'on-demand';

export interface Report {
    id: string;
    project_id: string;
    name: string;
    description: string | null;
    type: ReportType;
    category: ReportCategory;
    frequency: ReportFrequency | null;
    last_generated: string | null;
    next_run: string | null;
    is_scheduled: boolean;
    config: any;
    created_at: string;
    updated_at: string;
}

export function useReports(projectId: string | null) {
    const queryClient = useQueryClient();

    const query = useQuery({
        queryKey: ['reports', projectId],
        queryFn: async () => {
            if (!projectId) return [];

            const { data, error } = await supabase
                .from('reports')
                .select('*')
                .eq('project_id', projectId)
                .order('name');

            if (error) {
                toast.error('Failed to fetch reports');
                throw error;
            }

            return data as Report[];
        },
        enabled: !!projectId,
    });

    const createReport = useMutation({
        mutationFn: async (newReport: Partial<Report>) => {
            if (!projectId) throw new Error('Project ID is required');

            const { data, error } = await supabase
                .from('reports')
                .insert([{ ...newReport, project_id: projectId }])
                .select()
                .single();

            if (error) throw error;
            return data;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['reports', projectId] });
            toast.success('Report created successfully');
        },
        onError: (error) => {
            toast.error(`Failed to create report: ${error.message}`);
        },
    });

    const updateReport = useMutation({
        mutationFn: async ({ id, updates }: { id: string; updates: Partial<Report> }) => {
            const { data, error } = await supabase
                .from('reports')
                .update(updates)
                .eq('id', id)
                .select()
                .single();

            if (error) throw error;
            return data;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['reports', projectId] });
            toast.success('Report updated successfully');
        },
        onError: (error) => {
            toast.error(`Failed to update report: ${error.message}`);
        },
    });

    const deleteReport = useMutation({
        mutationFn: async (id: string) => {
            const { error } = await supabase
                .from('reports')
                .delete()
                .eq('id', id);

            if (error) throw error;
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['reports', projectId] });
            toast.success('Report deleted successfully');
        },
        onError: (error) => {
            toast.error(`Failed to delete report: ${error.message}`);
        },
    });

    return {
        ...query,
        createReport,
        updateReport,
        deleteReport,
    };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type RiskLevel = 'low' | 'medium' | 'high' | 'critical';
export type RiskStatus = 'identified' | 'analyzing' | 'mitigating' | 'closed' | 'accepted';

export interface Risk { id: string; project_id: string | null; title: string; description: string | null; category: string | null; probability: RiskLevel; impact: RiskLevel; status: RiskStatus; owner_id: string | null; owner_name: string | null; mitigation_plan: string | null; contingency_plan: string | null; triggers: string | null; linked_items: any[]; due_date: string | null; created_at: string; updated_at: string; closed_at: string | null; }
export interface RiskInput { title: string; description?: string; category?: string; probability?: RiskLevel; impact?: RiskLevel; status?: RiskStatus; owner_name?: string; mitigation_plan?: string; contingency_plan?: string; triggers?: string; due_date?: string; }

export function useRisks() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [risks, setRisks] = useState<Risk[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchRisks = useCallback(async () => {
    if (!projectId) { setRisks([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('risks').select('*').eq('project_id', projectId).order('created_at', { ascending: false });
      if (e) throw e;
      setRisks((data || []).map((r: any) => ({ ...r, probability: r.probability as RiskLevel, impact: r.impact as RiskLevel, status: r.status as RiskStatus, linked_items: Array.isArray(r.linked_items) ? r.linked_items : [] })));
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchRisks(); }, [fetchRisks]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('risks-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'risks', filter: `project_id=eq.${projectId}` }, () => fetchRisks()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchRisks]);

  const createRisk = async (input: RiskInput): Promise<Risk | null> => {
    if (!projectId) { toast.error('No project selected'); return null; }
    try {
      const { data, error: e } = await supabase.from('risks').insert({ project_id: projectId, title: input.title, description: input.description || null, category: input.category || null, probability: input.probability || 'medium', impact: input.impact || 'medium', status: input.status || 'identified', owner_name: input.owner_name || null, mitigation_plan: input.mitigation_plan || null, contingency_plan: input.contingency_plan || null, triggers: input.triggers || null, due_date: input.due_date || null }).select().single();
      if (e) throw e;
      const risk: Risk = { ...data, probability: data.probability as RiskLevel, impact: data.impact as RiskLevel, status: data.status as RiskStatus, linked_items: Array.isArray(data.linked_items) ? data.linked_items : [] };
      toast.success('Risk created'); return risk;
    } catch { toast.error('Failed to create risk'); return null; }
  };

  const updateRisk = async (id: string, updates: Partial<RiskInput>) => {
    try {
      const updateData: any = { ...updates };
      if (updates.status === 'closed') updateData.closed_at = new Date().toISOString();
      const { error: e } = await supabase.from('risks').update(updateData).eq('id', id);
      if (e) throw e; toast.success('Risk updated'); return true;
    } catch { toast.error('Failed to update risk'); return false; }
  };

  const deleteRisk = async (id: string) => { try { await supabase.from('risks').delete().eq('id', id); toast.success('Risk deleted'); return true; } catch { toast.error('Failed'); return false; } };

  const criticalRisks = risks.filter(r => r.impact === 'critical' || r.probability === 'critical');
  const openRisks = risks.filter(r => r.status !== 'closed');
  const mitigatingRisks = risks.filter(r => r.status === 'mitigating');

  return { risks, loading, error, refetch: fetchRisks, createRisk, updateRisk, deleteRisk, criticalRisks, openRisks, mitigatingRisks };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';

export interface NotebookSpreadsheet {
  id: string;
  notebook_id: string;
  name: string;
  color: string | null;
  sort_order: number;
  created_at: string;
  updated_at: string;
  // Linked project plan fields
  linked_project_id: string | null;
  linked_at: string | null;
  last_synced_at: string | null;
  sync_status: 'synced' | 'syncing' | 'error' | null;
  sync_direction: 'spreadsheet' | 'project' | 'both' | null;
}

export interface SpreadsheetSheet {
  id: string;
  spreadsheet_id: string;
  name: string;
  data: any[][]; // Array of rows, each row is an array of cell values
  column_widths: Record<string, number>;
  row_heights: Record<string, number>;
  frozen_rows: number;
  frozen_cols: number;
  sort_order: number;
  created_at: string;
  updated_at: string;
}

export function useSpreadsheets(notebookId: string | null) {
  const [spreadsheets, setSpreadsheets] = useState<NotebookSpreadsheet[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  const isValidUuid = (id: string | null | undefined): boolean => {
    if (!id) return false;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id);
  };

  const fetchSpreadsheets = async () => {
    if (!notebookId || !isValidUuid(notebookId)) {
      setSpreadsheets([]);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('notebook_spreadsheets')
        .select('*')
        .eq('notebook_id', notebookId)
        .order('sort_order', { ascending: true });

      if (error) throw error;
      // Cast the data to our interface type
      setSpreadsheets((data || []) as unknown as NotebookSpreadsheet[]);
    } catch (error) {
      console.error('Error fetching spreadsheets:', error);
    } finally {
      setLoading(false);
    }
  };

  const createSpreadsheet = async (name: string, color?: string) => {
    if (!notebookId || !isValidUuid(notebookId)) return null;

    try {
      const { data: spreadsheet, error } = await supabase
        .from('notebook_spreadsheets')
        .insert({
          notebook_id: notebookId,
          name,
          color,
          sort_order: spreadsheets.length,
        })
        .select()
        .single();

      if (error) throw error;

      // Create default first sheet
      await supabase
        .from('spreadsheet_sheets')
        .insert({
          spreadsheet_id: spreadsheet.id,
          name: 'Sheet 1',
          data: createEmptyGrid(20, 10),
          sort_order: 0,
        });

      toast({ title: 'Spreadsheet created' });
      return spreadsheet as unknown as NotebookSpreadsheet;
    } catch (error) {
      console.error('Error creating spreadsheet:', error);
      toast({ title: 'Error', description: 'Failed to create spreadsheet', variant: 'destructive' });
      return null;
    }
  };

  const updateSpreadsheet = async (id: string, updates: Partial<NotebookSpreadsheet>) => {
    try {
      const { error } = await supabase
        .from('notebook_spreadsheets')
        .update(updates)
        .eq('id', id);

      if (error) throw error;
    } catch (error) {
      console.error('Error updating spreadsheet:', error);
      toast({ title: 'Error', description: 'Failed to update spreadsheet', variant: 'destructive' });
    }
  };

  const deleteSpreadsheet = async (id: string) => {
    try {
      const { error } = await supabase
        .from('notebook_spreadsheets')
        .delete()
        .eq('id', id);

      if (error) throw error;
      toast({ title: 'Spreadsheet deleted' });
    } catch (error) {
      console.error('Error deleting spreadsheet:', error);
      toast({ title: 'Error', description: 'Failed to delete spreadsheet', variant: 'destructive' });
    }
  };

  useEffect(() => {
    fetchSpreadsheets();
  }, [notebookId]);

  // Subscribe to realtime updates
  useEffect(() => {
    if (!notebookId || !isValidUuid(notebookId)) return;

    const channel = supabase
      .channel(`spreadsheets-${notebookId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'notebook_spreadsheets',
          filter: `notebook_id=eq.${notebookId}`,
        },
        () => {
          fetchSpreadsheets();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [notebookId]);

  return {
    spreadsheets,
    loading,
    createSpreadsheet,
    updateSpreadsheet,
    deleteSpreadsheet,
    refetch: fetchSpreadsheets,
  };
}

export function useSheets(spreadsheetId: string | null) {
  const [sheets, setSheets] = useState<SpreadsheetSheet[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  const isValidUuid = (id: string | null | undefined): boolean => {
    if (!id) return false;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    return uuidRegex.test(id);
  };

  const fetchSheets = async () => {
    if (!spreadsheetId || !isValidUuid(spreadsheetId)) {
      setSheets([]);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('spreadsheet_sheets')
        .select('*')
        .eq('spreadsheet_id', spreadsheetId)
        .order('sort_order', { ascending: true });

      if (error) throw error;

      // Parse JSON data with proper typing
      const parsedData: SpreadsheetSheet[] = (data || []).map(sheet => ({
        id: sheet.id,
        spreadsheet_id: sheet.spreadsheet_id,
        name: sheet.name,
        data: Array.isArray(sheet.data) ? sheet.data as any[][] : [],
        column_widths: (typeof sheet.column_widths === 'object' && sheet.column_widths !== null && !Array.isArray(sheet.column_widths))
          ? sheet.column_widths as Record<string, number>
          : {},
        row_heights: (typeof sheet.row_heights === 'object' && sheet.row_heights !== null && !Array.isArray(sheet.row_heights))
          ? sheet.row_heights as Record<string, number>
          : {},
        frozen_rows: sheet.frozen_rows ?? 0,
        frozen_cols: sheet.frozen_cols ?? 0,
        sort_order: sheet.sort_order ?? 0,
        created_at: sheet.created_at,
        updated_at: sheet.updated_at,
      }));

      setSheets(parsedData);
    } catch (error) {
      console.error('Error fetching sheets:', error);
    } finally {
      setLoading(false);
    }
  };

  const createSheet = async (name: string = 'New Sheet') => {
    if (!spreadsheetId || !isValidUuid(spreadsheetId)) return null;

    try {
      const { data, error } = await supabase
        .from('spreadsheet_sheets')
        .insert({
          spreadsheet_id: spreadsheetId,
          name,
          data: createEmptyGrid(20, 10),
          sort_order: sheets.length,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    } catch (error) {
      console.error('Error creating sheet:', error);
      toast({ title: 'Error', description: 'Failed to create sheet', variant: 'destructive' });
      return null;
    }
  };

  const updateSheet = async (id: string, updates: Partial<SpreadsheetSheet>) => {
    try {
      const { error } = await supabase
        .from('spreadsheet_sheets')
        .update(updates)
        .eq('id', id);

      if (error) throw error;
    } catch (error) {
      console.error('Error updating sheet:', error);
      toast({ title: 'Error', description: 'Failed to save sheet', variant: 'destructive' });
    }
  };

  const deleteSheet = async (id: string) => {
    if (sheets.length <= 1) {
      toast({ title: 'Cannot delete', description: 'Spreadsheet must have at least one sheet', variant: 'destructive' });
      return;
    }

    try {
      const { error } = await supabase
        .from('spreadsheet_sheets')
        .delete()
        .eq('id', id);

      if (error) throw error;
      toast({ title: 'Sheet deleted' });
    } catch (error) {
      console.error('Error deleting sheet:', error);
      toast({ title: 'Error', description: 'Failed to delete sheet', variant: 'destructive' });
    }
  };

  useEffect(() => {
    fetchSheets();
  }, [spreadsheetId]);

  // Subscribe to realtime updates
  useEffect(() => {
    if (!spreadsheetId || !isValidUuid(spreadsheetId)) return;

    const channel = supabase
      .channel(`sheets-${spreadsheetId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'spreadsheet_sheets',
          filter: `spreadsheet_id=eq.${spreadsheetId}`,
        },
        () => {
          fetchSheets();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [spreadsheetId]);

  return {
    sheets,
    loading,
    createSheet,
    updateSheet,
    deleteSheet,
    refetch: fetchSheets,
  };
}

// Helper function to create an empty grid
function createEmptyGrid(rows: number, cols: number): any[][] {
  return Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () => '')
  );
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useProjectContext } from '@/contexts/ProjectContext';
import { toast } from 'sonner';

export type SprintStatus = 'planning' | 'active' | 'completed' | 'cancelled';

export interface Sprint { id: string; project_id: string | null; name: string; start_date: string; end_date: string; goal: string | null; velocity: number; capacity: number; status: SprintStatus; created_at: string; updated_at: string; }
export interface SprintInput { name: string; start_date: string; end_date: string; goal?: string; capacity?: number; status?: SprintStatus; }

export function useSprints() {
  const { settings } = useProjectContext();
  const projectId = settings.id;
  const [sprints, setSprints] = useState<Sprint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchSprints = useCallback(async () => {
    if (!projectId) { setSprints([]); setLoading(false); return; }
    try {
      setLoading(true);
      const { data, error: e } = await supabase.from('sprints').select('*').eq('project_id', projectId).order('start_date', { ascending: false });
      if (e) throw e;
      setSprints((data || []).map((s: any) => ({ ...s, status: s.status as SprintStatus })));
      setError(null);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  }, [projectId]);

  useEffect(() => { fetchSprints(); }, [fetchSprints]);

  useEffect(() => {
    if (!projectId) return;
    const channel = supabase.channel('sprints-changes').on('postgres_changes', { event: '*', schema: 'public', table: 'sprints', filter: `project_id=eq.${projectId}` }, () => fetchSprints()).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, fetchSprints]);

  const createSprint = async (input: SprintInput) => {
    if (!projectId) { toast.error('No project selected'); return null; }
    try {
      const { data, error: e } = await supabase.from('sprints').insert({ project_id: projectId, name: input.name, start_date: input.start_date, end_date: input.end_date, goal: input.goal || null, capacity: input.capacity || 0, status: input.status || 'planning' }).select().single();
      if (e) throw e;
      toast.success('Sprint created'); return data;
    } catch { toast.error('Failed to create sprint'); return null; }
  };

  const updateSprint = async (id: string, updates: Partial<SprintInput & { velocity?: number }>) => {
    try { const { error: e } = await supabase.from('sprints').update(updates).eq('id', id); if (e) throw e; toast.success('Sprint updated'); return true; } catch { toast.error('Failed to update sprint'); return false; }
  };

  const startSprint = async (id: string) => { const active = sprints.find(s => s.status === 'active'); if (active) await updateSprint(active.id, { status: 'completed' }); return updateSprint(id, { status: 'active' }); };
  const completeSprint = async (id: string, velocity: number) => updateSprint(id, { status: 'completed', velocity });
  const deleteSprint = async (id: string) => { try { await supabase.from('sprints').delete().eq('id', id); toast.success('Sprint deleted'); return true; } catch { toast.error('Failed'); return false; } };

  const activeSprint = sprints.find(s => s.status === 'active');
  const planningSprints = sprints.filter(s => s.status === 'planning');
  const completedSprints = sprints.filter(s => s.status === 'completed');
  const averageVelocity = completedSprints.length > 0 ? Math.round(completedSprints.reduce((sum, s) => sum + s.velocity, 0) / completedSprints.length) : 0;

  return { sprints, loading, error, refetch: fetchSprints, createSprint, updateSprint, startSprint, completeSprint, deleteSprint, activeSprint, planningSprints, completedSprints, averageVelocity };
}

